import pandas as pd
import networkx as nx
import matplotlib.pyplot as plt

# 1. Load dataset (first 50 rows)
file_path = "/content/Copy of LinkedIn_Dataset_work(1).xlsx"
df = pd.read_excel(file_path).head(50)

# 2. Clean columns
df['Full Name'] = df['Full Name'].fillna("Unknown").astype(str)
df['Connections'] = pd.to_numeric(df['Connections'], errors='coerce').fillna(0).astype(int)

# 3. Create graph
G = nx.Graph()

# 4. Add nodes with connections
for i, row in df.iterrows():
    G.add_node(row['Full Name'], connections=row['Connections'])

# 5. Add edges (rule: connect if connections differ by <= 5)
for i in range(len(df)):
    for j in range(i+1, len(df)):
        if abs(df.iloc[i]['Connections'] - df.iloc[j]['Connections']) <= 5:
            G.add_edge(df.iloc[i]['Full Name'], df.iloc[j]['Full Name'])

# 6. Draw graph
plt.figure(figsize=(14, 10))

# Try different layout
pos = nx.kamada_kawai_layout(G)   # alternative to spring layout

# Node sizes proportional to connections
node_sizes = [100 + 10*G.nodes[n]['connections'] for n in G.nodes()]

nx.draw_networkx_nodes(G, pos, node_size=node_sizes, node_color="skyblue", alpha=0.8)
nx.draw_networkx_edges(G, pos, alpha=0.4)

# Try plotting labels separately (optional: comment this if cluttered)
nx.draw_networkx_labels(G, pos, font_size=7, font_color="black")

plt.title("LinkedIn Network Graph (Sample 50 rows)", fontsize=14)
plt.axis("off")
plt.show()

