#TRIED MENU DRIVEN RATHER THAN LOOPS
import pandas as pd
import networkx as nx
import matplotlib.pyplot as plt

# Load dataset once
file_path = "/content/Copy of LinkedIn_Dataset_work(1).xlsx"
df = pd.read_excel(file_path)

# Clean columns
df['Full Name'] = df['Full Name'].fillna("Unknown").astype(str)
df['Connections'] = pd.to_numeric(df['Connections'], errors='coerce').fillna(0).astype(int)

def draw_network(start, end):
    subset = df.iloc[start:end]

    G = nx.Graph()

    for i, row in subset.iterrows():
        G.add_node(row['Full Name'], connections=row['Connections'])

    for i in range(len(subset)):
        for j in range(i+1, len(subset)):
            if abs(subset.iloc[i]['Connections'] - subset.iloc[j]['Connections']) <= 5:
                G.add_edge(subset.iloc[i]['Full Name'], subset.iloc[j]['Full Name'])

    plt.figure(figsize=(16, 12))
    pos = nx.spring_layout(G, k=0.3, iterations=30)

    node_sizes = [100 + 10*G.nodes[n]['connections'] for n in G.nodes()]
    nx.draw_networkx_nodes(G, pos, node_size=node_sizes, node_color="skyblue", alpha=0.8)
    nx.draw_networkx_edges(G, pos, alpha=0.4)
    nx.draw_networkx_labels(G, pos, font_size=7, font_color="black")

    plt.title(f"LinkedIn Network Graph (Rows {start+1}–{end})", fontsize=14)
    plt.axis("off")
    plt.show()

# Example usage:
draw_network(0, 50)   # draws first 50 rows
# Later you can call draw_network(50, 120), draw_network(200, 300), etc.

import pandas as pd
import networkx as nx
import matplotlib.pyplot as plt

# 1. Load dataset
file_path = "/content/Copy of LinkedIn_Dataset_work(1).xlsx"
df = pd.read_excel(file_path)

# 2. Clean columns
df['Full Name'] = df['Full Name'].fillna("Unknown").astype(str)
df['Connections'] = pd.to_numeric(df['Connections'], errors='coerce').fillna(0).astype(int)

# 3. Function to draw graph
def draw_network(start, end):
    subset = df.iloc[start:end]

    G = nx.Graph()

    for i, row in subset.iterrows():
        G.add_node(row['Full Name'], connections=row['Connections'])

    for i in range(len(subset)):
        for j in range(i+1, len(subset)):
            if abs(subset.iloc[i]['Connections'] - subset.iloc[j]['Connections']) <= 5:
                G.add_edge(subset.iloc[i]['Full Name'], subset.iloc[j]['Full Name'])

    plt.figure(figsize=(16, 12))
    pos = nx.spring_layout(G, k=0.3, iterations=30)

    node_sizes = [100 + 10*G.nodes[n]['connections'] for n in G.nodes()]
    nx.draw_networkx_nodes(G, pos, node_size=node_sizes, node_color="orange", alpha=0.8)
    nx.draw_networkx_edges(G, pos, alpha=0.4)
    nx.draw_networkx_labels(G, pos, font_size=7, font_color="black")

    plt.title(f"LinkedIn Network Graph (Rows {start+1}–{end})", fontsize=14)
    plt.axis("off")
    plt.show()

# 4. Menu-driven loop
while True:
    print("\n--- LinkedIn Network Visualizer ---")
    print("1. Draw network for a row range")
    print("2. Exit")

    choice = input("Enter your choice: ")

    if choice == "1":
        start = int(input("Enter start row (e.g., 0): "))
        end = int(input("Enter end row (e.g., 50): "))
        if start < 0 or end > len(df):
            print(f"❌ Please enter a valid range between 0 and {len(df)}")
        else:
            draw_network(start, end)

    elif choice == "2":
        print("Exiting... ✅")
        break
    else:
        print("❌ Invalid choice. Try again.")

import pandas as pd
import numpy as np
import matplotlib.pyplot as plt
import seaborn as sns
import ast
from collections import Counter
import re # Import the regular expressions library for text processing

# --- 1. SETUP AND DATA LOADING ---
print("--- Step 1: Loading and Initializing ---")

# Use a more modern and clean plot style
sns.set_theme(style="whitegrid", palette="viridis")

# Define the exact path to your Excel file
file_path = "Final_Dataset.xlsx"

# Load the dataset from the Excel file
try:
    df = pd.read_excel(file_path)
    print("✅ Dataset loaded successfully!")
    print(f"   - Dataset contains {df.shape[0]} rows and {df.shape[1]} columns.")
except FileNotFoundError:
    print(f"❌ ERROR: Could not find the file at the path: {file_path}")
    exit()
except Exception as e:
    print(f"❌ An unexpected error occurred: {e}")
    exit()

# --- 2. DATA CLEANING AND PREPROCESSING ---
print("\n--- Step 2: Cleaning and Preprocessing Data ---")
df.replace('--', np.nan, inplace=True)
df['Connections'] = pd.to_numeric(df['Connections'], errors='coerce')
df['Followers'] = pd.to_numeric(df['Followers'], errors='coerce')
print("✅ Cleaned and converted 'Connections' and 'Followers' columns.")

def parse_string_to_object(text):
    if pd.isna(text): return None
    try: return ast.literal_eval(str(text))
    except (ValueError, SyntaxError): return None
df['Skills_Parsed'] = df['Skills'].apply(parse_string_to_object)
print("✅ Parsed the 'Skills' column for analysis.")

# --- 3. ENHANCED EDA AND VISUALIZATION ---
print("\n--- Step 3: Generating Visualizations and Insights ---")

# A. Distribution of Profile Types
plt.figure(figsize=(12, 7))
ax = sns.countplot(y=df['Label(type of profile)'], order=df['Label(type of profile)'].value_counts().index, hue=df['Label(type of profile)'], dodge=False, palette='viridis', legend=False)
plt.title('Distribution of Profile Types', fontsize=18, fontweight='bold')
plt.xlabel('Number of Profiles', fontsize=12)
plt.ylabel('')
# Add count labels to the bars for clarity
for container in ax.containers:
    ax.bar_label(container, fmt='{:,.0f}', fontsize=12, padding=5)
plt.show()

# Print insights for this plot
total_profiles = len(df)
value_counts = df['Label(type of profile)'].value_counts()
print(f"📊 INSIGHT: The dataset is imbalanced. Out of {total_profiles:,} profiles:")
for label, count in value_counts.items():
    percentage = (count / total_profiles) * 100
    print(f"   - {count:,} ({percentage:.1f}%) are classified as '{label}'.")


# B. Distribution of Connections and Followers
fig, axes = plt.subplots(1, 2, figsize=(16, 6))
sns.histplot(df['Connections'].dropna(), bins=30, ax=axes[0], kde=True, color='#3498db')
axes[0].set_title('Distribution of Connections', fontsize=16, fontweight='bold')
axes[0].set_xlabel('Number of Connections')
sns.histplot(df['Followers'].dropna(), bins=30, ax=axes[1], kde=True, color='#e74c3c')
axes[1].set_title('Distribution of Followers', fontsize=16, fontweight='bold')
axes[1].set_xlabel('Number of Followers')
plt.suptitle('Most Users Have a Modest Network, with a Few Power Users', fontsize=20, fontweight='bold')
plt.tight_layout(rect=[0, 0.03, 1, 0.95])
plt.show()

print(f"\n📊 INSIGHT: The average number of connections is {df['Connections'].mean():.0f}, but the median is {df['Connections'].median():.0f}.")
print(f"   - This difference indicates that a few highly-connected users skew the average.")


# C. Analysis of Top 20 Skills
all_skills = [skill for item in df['Skills_Parsed'].dropna() if isinstance(item, dict) for skill in item.values()]
skill_counts = Counter(all_skills)
top_20_skills = pd.DataFrame(skill_counts.most_common(20), columns=['Skill', 'Count'])

plt.figure(figsize=(12, 8))
ax_skills = sns.barplot(x='Count', y='Skill', data=top_20_skills, hue='Skill', dodge=False, palette='plasma', legend=False)
plt.title('Top 20 Most Common Professional Skills', fontsize=18, fontweight='bold')
plt.xlabel('Frequency', fontsize=12)
plt.ylabel('Skill', fontsize=12)
ax_skills.bar_label(ax_skills.containers[0], padding=3)
plt.show()

print(f"\n📊 INSIGHT: The most sought-after skill is '{top_20_skills['Skill'].iloc[0]}', appearing {top_20_skills['Count'].iloc[0]:,} times.")
print(f"   - The skill set is heavily focused on business, management, and sales roles.")

# D. Connections vs. Followers by Profile Type
plt.figure(figsize=(12, 8))
sns.scatterplot(data=df, x='Connections', y='Followers', hue='Label(type of profile)', alpha=0.7, palette='magma', s=50)
plt.title('Connections vs. Followers by Profile Type', fontsize=18, fontweight='bold')
plt.xlabel('Connections (Log Scale)', fontsize=12)
plt.ylabel('Followers (Log Scale)', fontsize=12)
plt.xscale('log')
plt.yscale('log')
plt.legend(title='Profile Type', loc='upper left')
plt.show()

print("\n📊 INSIGHT: There is a strong, positive correlation between Connections and Followers.")
print("   - Job Providers (purple dots) often appear in the upper-right quadrant, indicating larger networks.")


# E. Distribution of Connections by Profile Type
plt.figure(figsize=(12, 8))
sns.boxplot(data=df, x='Label(type of profile)', y='Connections', hue='Label(type of profile)', dodge=False, palette='pastel', legend=False)
plt.title('How Connections Vary by Profile Type', fontsize=18, fontweight='bold')
plt.xlabel('Profile Type', fontsize=12)
plt.ylabel('Number of Connections', fontsize=12)
plt.ylim(0, 600)
plt.show()

# --- 4. DEEPER DIVE: EXPERIENCE ANALYSIS ---
print("\n--- Step 4: Deeper Analysis of Work Experience ---")

df['Experiences_Parsed'] = df['Experiences'].apply(parse_string_to_object)

def calculate_duration_months(duration_str):
    if not isinstance(duration_str, str):
        return np.nan

    years = 0
    months = 0

    # Find years
    year_match = re.search(r'(\d+)\s+yrs?', duration_str, re.IGNORECASE)
    if year_match:
        years = int(year_match.group(1))

    # Find months
    month_match = re.search(r'(\d+)\s+mos?', duration_str, re.IGNORECASE)
    if month_match:
        months = int(month_match.group(1))

    return (years * 12) + months

# Calculate total experience for each user
total_experience = []
for index, row in df.iterrows():
    total_months = 0
    if isinstance(row['Experiences_Parsed'], dict):
        for exp in row['Experiences_Parsed'].values():
            if 'Duration' in exp:
                total_months += calculate_duration_months(exp['Duration'])
    total_experience.append(total_months if total_months > 0 else np.nan)

df['TotalExperienceYears'] = np.array(total_experience) / 12

# Plotting the results
plt.figure(figsize=(12, 8))
sns.boxplot(data=df, x='Label(type of profile)', y='TotalExperienceYears', hue='Label(type of profile)', dodge=False, palette='crest', legend=False)
plt.title('Total Career Experience by Profile Type', fontsize=18, fontweight='bold')
plt.xlabel('Profile Type', fontsize=12)
plt.ylabel('Total Experience (Years)', fontsize=12)
plt.ylim(0, 40) # Set a reasonable limit to exclude extreme outliers
plt.show()

# Print final insights
median_exp = df.groupby('Label(type of profile)')['TotalExperienceYears'].median()
print("\n📊 INSIGHT: Analyzing total career duration reveals differences:")
for label, exp in median_exp.items():
    print(f"   - The median total experience for a '{label}' is {exp:.1f} years.")

print("\n--- ✅ EDA Script Finished ---")

