import pandas as pd
import networkx as nx
import matplotlib.pyplot as plt

# 1. Load dataset
file_path = "/content/Final_Dataset.xlsx"
df = pd.read_excel(file_path)

# 2. Clean columns
df['Full Name'] = df['Full Name'].fillna("Unknown").astype(str)
df['Connections'] = pd.to_numeric(df['Connections'], errors='coerce').fillna(0).astype(int)

# 3. Function to draw graph
def draw_network(start, end):
    subset = df.iloc[start:end]

    G = nx.Graph()

    for i, row in subset.iterrows():
        G.add_node(row['Full Name'], connections=row['Connections'])

    for i in range(len(subset)):
        for j in range(i+1, len(subset)):
            if abs(subset.iloc[i]['Connections'] - subset.iloc[j]['Connections']) <= 5:
                G.add_edge(subset.iloc[i]['Full Name'], subset.iloc[j]['Full Name'])

    plt.figure(figsize=(16, 12))
    pos = nx.spring_layout(G, k=0.3, iterations=30)

    node_sizes = [100 + 10*G.nodes[n]['connections'] for n in G.nodes()]
    nx.draw_networkx_nodes(G, pos, node_size=node_sizes, node_color="orange", alpha=0.8)
    nx.draw_networkx_edges(G, pos, alpha=0.4)
    nx.draw_networkx_labels(G, pos, font_size=7, font_color="black")

    plt.title(f"LinkedIn Network Graph (Rows {start+1}–{end})", fontsize=14)
    plt.axis("off")
    plt.show()

# 4. Menu-driven loop
while True:
    print("\n--- LinkedIn Network Visualizer ---")
    print("1. Draw network for a row range")
    print("2. Exit")

    choice = input("Enter your choice: ")

    if choice == "1":
        start = int(input("Enter start row (e.g., 0): "))
        end = int(input("Enter end row (e.g., 50): "))
        if start < 0 or end > len(df):
            print(f"❌ Please enter a valid range between 0 and {len(df)}")
        else:
            draw_network(start, end)

    elif choice == "2":
        print("Exiting... ✅")
        break
    else:
        print("❌ Invalid choice. Try again.")

import os
import pandas as pd
import networkx as nx
import matplotlib.pyplot as plt
import numpy as np
import seaborn as sns

# -------------------------
# INSIGHT HELPERS (one-line insight + one-line summary)
# -------------------------
def one_line_stats(series):
    arr = np.array(series)
    mean = np.mean(arr)
    median = np.median(arr)
    std = np.std(arr)
    return mean, median, std

def print_bar_insight(df, metric):
    try:
        top = df.sort_values(metric, ascending=False).head(3)
        n = len(df)
        mean, median, std = one_line_stats(df[metric].values)
        top0_name = top.iloc[0]['node'] if not top.empty else "N/A"
        top0_val = top.iloc[0][metric] if not top.empty else 0
        top1_val = top.iloc[1][metric] if len(top) > 1 else 0
        rel = (top0_val / top1_val - 1) if top1_val else float('inf')
        rel_text = f"{rel:.2f}x higher than 2nd" if np.isfinite(rel) and rel != float('inf') else "much higher"
        print(f"Insight: Top by {metric}: {top0_name} = {top0_val:.3f} ({rel_text}).")
        print(f"Summary: {metric} across {n} nodes — mean={mean:.3f}, median={median:.3f}, std={std:.3f}.")
    except Exception as e:
        print("Insight: (could not compute bar insight)"); print("Summary: (error)", e)

def print_hist_insight(df, metric):
    try:
        vals = np.array(df[metric])
        zeros = np.sum(vals == 0)
        pct_zero = 100 * zeros / len(vals) if len(vals) else 0
        mean, median, std = one_line_stats(vals)
        skew = (np.mean((vals - mean)**3) / (std**3)) if std != 0 else 0
        skew_label = "right-skewed" if skew > 0.5 else ("left-skewed" if skew < -0.5 else "roughly symmetric")
        print(f"Insight: {metric} histogram — {pct_zero:.1f}% zeros; distribution is {skew_label}.")
        print(f"Summary: {metric} — mean={mean:.5f}, median={median:.5f}, std={std:.5f}.")
    except Exception as e:
        print("Insight: (could not compute hist insight)"); print("Summary: (error)", e)

def print_scatter_insight(df, x, y):
    try:
        xv = np.array(df[x]); yv = np.array(df[y])
        if len(xv) < 2:
            print("Insight: (not enough points)"); print("Summary: (too few points)")
            return
        corr = np.corrcoef(xv, yv)[0,1]
        top_by_y = df.sort_values(y, ascending=False).head(3)['node'].tolist()
        print(f"Insight: Correlation({x}, {y}) = {corr:.3f}.")
        print(f"Summary: Top by {y}: {', '.join(top_by_y)}.")
    except Exception as e:
        print("Insight: (could not compute scatter insight)"); print("Summary: (error)", e)

def print_network_insight(G):
    try:
        n_nodes = G.number_of_nodes()
        n_edges = G.number_of_edges()
        comps = list(nx.connected_components(G))
        n_comps = len(comps)
        largest_size = max((len(c) for c in comps), default=0)
        avg_deg = np.mean([d for _, d in G.degree()]) if n_nodes else 0
        clustering = nx.average_clustering(G) if n_nodes else 0
        print(f"Insight: Graph has {n_comps} components; largest component size = {largest_size}.")
        print(f"Summary: Nodes={n_nodes}, Edges={n_edges}, avg_degree={avg_deg:.3f}, avg_clustering={clustering:.3f}.")
    except Exception as e:
        print("Insight: (could not compute network insight)"); print("Summary: (error)", e)

def print_corr_insight(metrics_df):
    try:
        corr = metrics_df.corr()
        corr_vals = corr.abs().where(~np.eye(corr.shape[0], dtype=bool))
        max_idx = np.unravel_index(np.nanargmax(corr_vals.values), corr_vals.shape)
        a = corr_vals.index[max_idx[0]]
        b = corr_vals.columns[max_idx[1]]
        max_val = corr.loc[a, b]
        print(f"Insight: Highest correlation is between '{a}' and '{b}' = {max_val:.3f}.")
        print("Summary: Correlation matrix diagonal=1; inspect pairs with abs(corr)>0.5 for strong relationships.")
    except Exception as e:
        print("Insight: (could not compute corr insight)"); print("Summary: (error)", e)

# -------------------------
# PLOTTING HELPERS (unchanged behavior + insights)
# -------------------------
def plot_bar(df, metric, top_k=None, horizontal=False, figsize=None, title=None, save=False, filename=None, plot_all_flag=True):
    if top_k is None or top_k == 'all' or plot_all_flag:
        plot_df = df.sort_values(metric, ascending=False)
    else:
        plot_df = df.sort_values(metric, ascending=False).head(top_k)
    n = len(plot_df)
    if n == 0:
        print(f"Skipping plot for '{metric}' as there is no data to plot.")
        return
    if figsize is None:
        if horizontal:
            figsize = (10, max(4, 0.25 * n))
        else:
            figsize = (max(6, 0.35 * n), 6)
    plt.figure(figsize=figsize)
    if horizontal:
        plt.barh(plot_df['node'], plot_df[metric])
        plt.gca().invert_yaxis()
        plt.xlabel(metric)
    else:
        plt.bar(plot_df['node'], plot_df[metric])
        plt.xticks(rotation=90)
        plt.ylabel(metric)
    plt.title(title or f"{metric} (n={n})")
    plt.tight_layout()
    if save:
        fn = filename or f"bar_{metric}.png"
        plt.savefig(fn, dpi=200)
        print("Saved", fn)
    plt.show()
    print(f"\n--- {title or metric} ---")
    print_bar_insight(plot_df, metric)
    print("------------------------------\n")

def plot_hist(df, metric, bins=25, figsize=(8,4), save=False, filename=None):
    plt.figure(figsize=figsize)
    plt.hist(df[metric], bins=bins)
    plt.xlabel(metric)
    plt.ylabel("count")
    plt.title(f"Histogram of {metric}")
    plt.tight_layout()
    if save:
        fn = filename or f"hist_{metric}.png"
        plt.savefig(fn, dpi=200)
        print("Saved", fn)
    plt.show()
    print(f"\n--- Histogram: {metric} ---")
    print_hist_insight(df, metric)
    print("------------------------------\n")

def scatter_label_top(df, x, y, top_n=8, figsize=(8,6), save=False, filename=None):
    plt.figure(figsize=figsize)
    plt.scatter(df[x], df[y], alpha=0.7)
    plt.xlabel(x); plt.ylabel(y); plt.title(f"{y} vs {x}")
    top = df.sort_values(y, ascending=False).head(top_n)
    for _, r in top.iterrows():
        plt.text(r[x], r[y], r['node'], fontsize=8)
    plt.tight_layout()
    if save:
        fn = filename or f"scatter_{x}_vs_{y}.png"
        plt.savefig(fn, dpi=200)
        print("Saved", fn)
    plt.show()
    print(f"\n--- Scatter: {y} vs {x} ---")
    print_scatter_insight(df, x, y)
    print("------------------------------\n")

def draw_network_visual(G, centrality_df, size_metric='degree_count', color_metric='pagerank', label_top=12, figsize=(12,9), save=False):
    pos = nx.spring_layout(G, k=0.25, iterations=50, seed=42)
    size_map = centrality_df.set_index('node')[size_metric].to_dict()
    color_map = centrality_df.set_index('node')[color_metric].to_dict()
    sizes = [100 + 40 * size_map.get(n, 0) for n in G.nodes()]
    colors = [color_map.get(n, 0.0) for n in G.nodes()]
    plt.figure(figsize=figsize)
    nodes_drawn = nx.draw_networkx_nodes(G, pos, node_size=sizes, node_color=colors)
    nx.draw_networkx_edges(G, pos, alpha=0.25)
    top_nodes = centrality_df.sort_values(color_metric, ascending=False).head(label_top)['node'].tolist()
    labels = {n: n if n in top_nodes else "" for n in G.nodes()}
    nx.draw_networkx_labels(G, pos, labels, font_size=8)
    plt.colorbar(nodes_drawn)
    plt.title(f"Network (size={size_metric}, color={color_metric})")
    plt.axis('off')
    plt.tight_layout()
    if save:
        fn = f"network_{size_metric}_{color_metric}.png"
        plt.savefig(fn, dpi=200)
        print("Saved", fn)
    plt.show()
    print(f"\n--- Network Visual ---")
    print_network_insight(G)
    print("------------------------------\n")

# -------------------------------------------------------------
# ✨ CORE ANALYSIS FUNCTION ✨
# -------------------------------------------------------------
def perform_analysis(df, name_col, connections_col, start, end, conn_threshold, top_k, plot_all, output_csv_template):
    """
    This function contains the core logic for building the graph,
    calculating centralities, and generating plots for a given data slice.
    """
    print(f"\n{'='*20}\nRunning analysis for rows {start} to {end-1}...\n{'='*20}")

    # Generate a unique CSV name for this analysis run
    output_csv = output_csv_template.replace(".csv", f"_{start}-{end}.csv")

    # -------------------------
    # SUBSET DATA
    # -------------------------
    subset = df.iloc[start:end].reset_index(drop=True)
    print(f"Created subset with {len(subset)} rows.")

    # -------------------------
    # BUILD GRAPH
    # -------------------------
    G = nx.Graph()
    for _, row in subset.iterrows():
        G.add_node(row[name_col], connections=int(row[connections_col]))

    for i in range(len(subset)):
        for j in range(i + 1, len(subset)):
            if abs(int(subset.iloc[i][connections_col]) - int(subset.iloc[j][connections_col])) <= conn_threshold:
                G.add_edge(subset.iloc[i][name_col], subset.iloc[j][name_col])

    nodes = list(G.nodes())
    if len(nodes) == 0:
        print("Error: Graph has no nodes. Check your row range and data.")
        return

    print(f"Graph built: {G.number_of_nodes()} nodes, {G.number_of_edges()} edges.")

    # -------------------------
    # CALCULATE CENTRALITIES
    # -------------------------
    print("Calculating centralities...")
    degree_count = dict(G.degree())
    degree_centrality = nx.degree_centrality(G)
    betweenness = nx.betweenness_centrality(G, normalized=True)
    closeness = nx.closeness_centrality(G)
    pagerank = nx.pagerank(G, alpha=0.85)

    try:
        eigenvector = nx.eigenvector_centrality_numpy(G)
    except Exception:
        try:
            largest_cc = max(nx.connected_components(G), key=len)
            eigen_sub = nx.subgraph(G, largest_cc).copy()
            eigen_subv = nx.eigenvector_centrality_numpy(eigen_sub)
            eigenvector = {n: eigen_subv.get(n, 0.0) for n in G.nodes()}
        except Exception:
            eigenvector = {n: 0.0 for n in G.nodes()}

    is_isolate = {n: (degree_count.get(n, 0) == 0) for n in G.nodes()}

    centrality_df = pd.DataFrame({
        'node': nodes,
        'degree': [degree_centrality.get(n, 0.0) for n in nodes],
        'betweenness': [betweenness.get(n, 0.0) for n in nodes],
        'closeness': [closeness.get(n, 0.0) for n in nodes],
        'pagerank': [pagerank.get(n, 0.0) for n in nodes],
        'eigenvector': [eigenvector.get(n, 0.0) for n in nodes],
        'degree_count': [degree_count.get(n, 0) for n in nodes],
        'is_isolate': [is_isolate.get(n, False) for n in nodes]
    })

    centrality_df.to_csv(output_csv, index=False)
    print(f"Saved centralities table to: {os.path.abspath(output_csv)}")

    pd.set_option('display.max_rows', None)
    pd.set_option('display.max_columns', None)
    print("\n=== CENTRALITIES FOR ALL NODES ===")
    print(centrality_df.sort_values(['degree_count', 'pagerank'], ascending=[False, False]).to_string(index=False))
    pd.reset_option('display.max_rows')

    # -------------------------
    # MAKE PLOTS
    # -------------------------
    print("\nGenerating plots...")
    plot_bar(centrality_df, 'degree_count', top_k=None, horizontal=True, title="Degree (raw count)", plot_all_flag=True)

    if plot_all:
        plot_bar(centrality_df, 'betweenness', top_k=None, horizontal=False, title="Betweenness (all nodes)", plot_all_flag=True)
        plot_bar(centrality_df, 'pagerank', top_k=None, horizontal=False, title="PageRank (all nodes)", plot_all_flag=True)
    else:
        plot_bar(centrality_df, 'betweenness', top_k=top_k, horizontal=False, title=f"Top {top_k} by betweenness", plot_all_flag=False)
        plot_bar(centrality_df, 'pagerank', top_k=top_k, horizontal=False, title=f"Top {top_k} by PageRank", plot_all_flag=False)

    plot_hist(centrality_df, 'degree_count', bins=30)
    plot_hist(centrality_df, 'betweenness', bins=30)
    plot_hist(centrality_df, 'pagerank', bins=30)
    plot_hist(centrality_df, 'eigenvector', bins=30)

    scatter_label_top(centrality_df, 'degree_count', 'betweenness', top_n=10)
    scatter_label_top(centrality_df, 'degree_count', 'pagerank', top_n=10)

    draw_network_visual(G, centrality_df, size_metric='degree_count', color_metric='pagerank', label_top=12)

    # -------------------------
    # CORRELATION HEATMAP
    # -------------------------
    print("\nGenerating correlation heatmap...")
    metrics_df = centrality_df[['degree', 'betweenness', 'closeness', 'pagerank', 'eigenvector', 'degree_count']]
    corr_matrix = metrics_df.corr()

    plt.figure(figsize=(10, 8))
    sns.heatmap(corr_matrix, annot=True, cmap='viridis', fmt='.2f', linewidths=.5)
    plt.title('Correlation Heatmap of Centrality Measures')
    plt.xticks(rotation=45, ha='right')
    plt.yticks(rotation=0)
    plt.tight_layout()
    plt.savefig(f"centrality_heatmap_{start}-{end}.png", dpi=200)
    print(f"Saved centrality_heatmap_{start}-{end}.png")
    plt.show()

    print("\n--- Correlation Heatmap ---")
    print_corr_insight(metrics_df)
    print("------------------------------\n")

    print(f"\n--- Analysis for rows {start}-{end-1} complete! ---")

# -------------------------------------------------------------
# ✨ MAIN MENU FUNCTION ✨
# -------------------------------------------------------------
def main():
    """
    Main function to run the menu-driven application.
    """
    # -------------------------
    # CONFIG - can be changed here
    # -------------------------
    file_path_candidates = [
        "/content/Final_Dataset.xlsx"  # Add other potential paths here
    ]
    name_col = "Full Name"
    connections_col = "Connections"
    output_csv_template = "centralities_full.csv"

    # Analysis parameters
    conn_threshold = 5
    top_k = 12
    plot_all = True

    # -------------------------
    # LOAD DATA (once at the start)
    # -------------------------
    file_path = next((p for p in file_path_candidates if os.path.exists(p)), None)
    if file_path is None:
        print("Error: Dataset not found. Please check the 'file_path_candidates' list.")
        return

    try:
        print(f"Loading data from '{file_path}'...")
        if file_path.endswith('.csv'):
            df = pd.read_csv(file_path)
        else:
            df = pd.read_excel(file_path)
        print(f"Successfully loaded. Total rows available: {len(df)}")
    except Exception as e:
        print(f"Error: Failed to read the file. Please ensure it is a valid Excel or CSV file. Error: {e}")
        return

    # Clean data once
    df[name_col] = df[name_col].fillna("Unknown").astype(str)
    df[connections_col] = pd.to_numeric(df[connections_col], errors="coerce").fillna(0).astype(int)

    # Menu state variables
    start_row = None
    end_row = None

    # -------------------------
    # MENU LOOP
    # -------------------------
    while True:
        print("\n===== Network Analysis Menu =====")
        current_range = f"Rows {start_row} to {end_row - 1}" if start_row is not None else "Not set"
        print(f"1. Set Row Range for Analysis (Current: {current_range})")
        print("2. Run Analysis on Selected Range")
        print("3. Exit")

        choice = input("Enter your choice (1-3): ")

        if choice == '1':
            try:
                print(f"\nThe dataset has {len(df)} rows (indexed 0 to {len(df)-1}).")
                temp_start = int(input(f"Enter the START row index [0-{len(df)-1}]: "))
                temp_end = int(input(f"Enter the END row index (exclusive) [1-{len(df)}]: "))

                if 0 <= temp_start < temp_end <= len(df):
                    start_row = temp_start
                    end_row = temp_end
                    print(f"✅ Range set successfully to analyze {end_row - start_row} rows (from index {start_row} to {end_row - 1}).")
                else:
                    print("❌ Invalid range. Please ensure that 0 <= start < end <= total rows.")

            except ValueError:
                print("❌ Invalid input. Please enter integers for the row range.")

        elif choice == '2':
            if start_row is None or end_row is None:
                print("⚠️ Please set the row range first using option 1.")
            else:
                # Call the analysis function with the current settings
                perform_analysis(df, name_col, connections_col, start_row, end_row, conn_threshold, top_k, plot_all, output_csv_template)

        elif choice == '3':
            print("Exiting the program. Goodbye! 👋")
            break

        else:
            print("Invalid choice. Please enter a number between 1 and 3.")


if __name__ == "__main__":
    main()

