# --- 2. DEFINE THE FILE TO LOAD ---
file_name = '/content/Dataset_Final.xlsx' # This should be your .xlsx file

# --- 3. LOAD DATA ---
print(f"Loading data from {file_name}...")
try:
    df = pd.read_excel(file_name)
    print("Data loaded successfully.")

except FileNotFoundError:
    print(f"--- ERROR ---")
    print(f"File not found: '{file_name}'")
    print("Please make sure you have uploaded the .xlsx file.")
    raise
except Exception as e:
    print(f"Error loading file: {e}")
    raise

# --- **NEW** Clean 'Full Name' BUT DO NOT REMOVE DUPLICATES ---
df['Full Name'] = df['Full Name'].astype(str).str.strip()
print(f"Total rows loaded: {len(df)}")
# --------------------------------------------------

# Clean Connections column (needed for new graph logic)
df['Connections'] = pd.to_numeric(df['Connections'], errors='coerce').fillna(0).astype(int)

# --- **CHANGED** We do NOT set the index to 'Full Name'.
# The default integer index (0, 1, 2...) is now our unique 'node_id'.

# --- 4. MENU-DRIVEN SELECTION ---
print("\n--- Network Selection Menu ---")
available_types = sorted(df['Label(type of profile)'].unique())
print(f"Available 'Label(type of profile)' values: {available_types}")

chosen_type = input("Enter the 'Label(type of profile)' you want to process (e.g., 0, 1, 10, 11): ")

# Validate input
try:
    chosen_type = int(chosen_type)
    if chosen_type not in MASTER_SAMPLE_PLAN:
        print("Error: No sample plan defined for this type.")
        raise ValueError
    if chosen_type not in available_types:
        print("Error: This type is not in the dataset.")
        raise ValueError
except ValueError:
    print("Invalid input. Exiting.")
    raise

# --- 5. SELECT SAMPLE PLAN AND SUBSET DATA ---
sample_plan = MASTER_SAMPLE_PLAN[chosen_type]
print(f"\nLoaded sample plan for type {chosen_type}.")

df_subset = df[df['Label(type of profile)'] == chosen_type].copy()
if df_subset.empty:
    print(f"No data found for type {chosen_type}. Exiting.")
    raise ValueError

print(f"Found {len(df_subset)} nodes for this type.")
print("Original counts in this subset:")
print(df_subset['Label'].value_counts().to_string())

# --- 6. **CHANGED** DYNAMIC GRAPH CREATION (using Integer Index as Node ID) ---
print("\nBuilding graph based on 'Connections' similarity...")
G = nx.Graph()

# Add all nodes first from the subset
# The index (row.name) is now the unique integer ID
for i, row in df_subset.iterrows():
    G.add_node(i, connections=row['Connections'], full_name=row['Full Name'])

# Compare all pairs to add edges
subset_node_indices = list(df_subset.index) # This is now a list of integers
for i in range(len(subset_node_indices)):
    for j in range(i + 1, len(subset_node_indices)):
        node_A_index = subset_node_indices[i] # e.g., 0
        node_B_index = subset_node_indices[j] # e.g., 1

        # --- **FIXED** Get connection counts using .loc on the unique integer index ---
        conns_A = df_subset.loc[node_A_index, 'Connections']
        conns_B = df_subset.loc[node_B_index, 'Connections']

        # This is the logic you requested
        if abs(conns_A - conns_B) <= 5:
            G.add_edge(node_A_index, node_B_index)
# --- End of New Graph Logic ---

print(f"Graph built: {G.number_of_nodes()} nodes, {G.number_of_edges()} edges.")

# --- 7. GRAPH VISUALIZATION ---
try:
    plt.figure(figsize=(15, 15))
    print("Drawing graph... (this may take time for large graphs)")

    pos = nx.spring_layout(G, k=0.15, iterations=20)

    # Node size based on 'Connections' attribute we just added
    node_sizes = [10 + G.nodes[n]['connections'] for n in G.nodes()]

    nx.draw(G, pos=pos, node_size=node_sizes, width=0.2, with_labels=False, alpha=0.7, node_color='blue')

    plt.title(f"Graph for Type {chosen_type} ({G.number_of_nodes()} nodes, {G.number_of_edges()} edges)", fontsize=20)
    graph_filename = f"graph_type_{chosen_type}.png"
    plt.savefig(graph_filename)
    print(f"Graph image saved to {graph_filename}")
except Exception as e:
    print(f"Could not draw graph. Error: {e}")

# --- 8. Calculate Centrality ---
print("\nCalculating centrality... (This may take a few minutes)")
# Centrality dicts are now keyed by integer index
degree_cent = nx.degree_centrality(G)
betweenness_cent = nx.betweenness_centrality(G)

# Map scores back to the df_subset
df_subset['degree'] = df_subset.index.map(degree_cent)
df_subset['betweenness'] = df_subset.index.map(betweenness_cent)
print("Centrality calculation complete.")

# --- 9. CASCADING (POOL) STRATIFICATION FUNCTION ---
def get_stratified_sample(df_label_group, plan):
    """
    Takes a df for a single label and samples it based on
    a robust, cascading "pool" centrality split.
    This GUARANTEES the total sample count.
    """
    centrality_col = plan['centrality_col']
    total_samples = plan['low'] + plan['mid'] + plan['high']

    if df_label_group.empty:
        print(f"  > Group is empty. Returning 0 nodes.")
        return pd.DataFrame()

    if total_samples == 0:
        return pd.DataFrame()

    # Fallback for groups smaller than total sample
    if len(df_label_group) <= total_samples:
        print(f"  Warning: Group size ({len(df_label_group)}) is less than or equal to sample size ({total_samples}). Returning all nodes.")
        return df_label_group

    print(f"  Creating robust centrality bins for {centrality_col}...")

    scores = df_label_group[centrality_col]
    zero_nodes = scores[scores == 0]
    non_zero_nodes = scores[scores > 0]

    # Use sets for faster operations
    # The node IDs are now integers
    node_pools = {
        'low': set(zero_nodes.index),
        'mid': set(),
        'high': set()
    }

    if non_zero_nodes.empty:
        print("  Warning: All nodes have 0 centrality. 'mid' and 'high' bins will be empty.")
    else:
        median_nonzero = non_zero_nodes.median()
        if median_nonzero == 0:
             median_nonzero = non_zero_nodes[non_zero_nodes > 0].median()
             if pd.isna(median_nonzero):
                 median_nonzero = non_zero_nodes.mean()

        node_pools['mid'] = set(non_zero_nodes[non_zero_nodes <= median_nonzero].index)
        node_pools['high'] = set(non_zero_nodes[non_zero_nodes > median_nonzero].index)

    print(f"  Bin sizes: Low ({len(node_pools['low'])}), Mid ({len(node_pools['mid'])}), High ({len(node_pools['high'])})")

    # --- CASCADING "POOL" SAMPLE LOGIC ---

    final_node_list = set()

    # 1. Try to sample from 'High' bin
    nodes_to_find_high = plan['high']
    available_high = list(node_pools['high'])

    sample_high_count = min(nodes_to_find_high, len(available_high))
    sample_high = set(random.sample(available_high, sample_high_count))
    final_node_list.update(sample_high)

    remainder_nodes_high = node_pools['high'] - sample_high
    node_pools['mid'].update(remainder_nodes_high) # Add them to the pool

    print(f"  > High bin: Wanted {nodes_to_find_high}, Got {len(sample_high)}. Passing {len(remainder_nodes_high)} unused nodes to 'Mid' pool.")

    # 2. Try to sample from 'Mid' bin
    nodes_to_find_mid = plan['mid']
    available_mid = list(node_pools['mid'])

    sample_mid_count = min(nodes_to_find_mid, len(available_mid))
    sample_mid = set(random.sample(available_mid, sample_mid_count))
    final_node_list.update(sample_mid)

    remainder_nodes_mid = node_pools['mid'] - sample_mid
    node_pools['low'].update(remainder_nodes_mid) # Add them to the pool

    print(f"  > Mid bin: Wanted {nodes_to_find_mid}, Got {len(sample_mid)}. Passing {len(remainder_nodes_mid)} unused nodes to 'Low' pool.")

    # 3. Sample remaining nodes from 'Low' bin
    nodes_sampled_so_far = len(final_node_list)
    nodes_to_find_low = total_samples - nodes_sampled_so_far
    available_low = list(node_pools['low'])

    if nodes_to_find_low > len(available_low):
        print(f"  CRITICAL Warning: Not enough nodes in all pools combined. Taking all {len(available_low)} 'Low' nodes.")
        sample_low = set(available_low)
    else:
        sample_low = set(random.sample(available_low, nodes_to_find_low))

    final_node_list.update(sample_low)
    print(f"  > Low bin: Wanted {nodes_to_find_low}, Got {len(sample_low)}.")

    # Return from the GROUP, which has the centrality scores
    return df_label_group.loc[list(final_node_list)]

# --- 10. Execute Sampling ---
print("\nStarting stratified sampling process...")
all_samples = []

with warnings.catch_warnings():
    warnings.simplefilter("ignore")

    print("\nProcessing Job Providers...")
    df_provider = df_subset[df_subset['Label'] == 'Job Provider'].copy()
    sample_provider = get_stratified_sample(df_provider, sample_plan['Job Provider'])
    all_samples.append(sample_provider)

    print("\nProcessing Job Seekers...")
    df_seeker = df_subset[df_subset['Label'] == 'Job Seeker'].copy()
    sample_seeker = get_stratified_sample(df_seeker, sample_plan['Job Seeker'])
    all_samples.append(sample_seeker)

    print("\nProcessing Others...")
    df_other = df_subset[df_subset['Label'] == 'Other'].copy()
    sample_other = get_stratified_sample(df_other, sample_plan['Other'])
    all_samples.append(sample_other)

final_sample_df = pd.concat(all_samples)

print("\n--- Sampling Complete ---")
print(f"Total nodes sampled: {len(final_sample_df)}")
print("Final Sample Breakdown by Label:")
print(final_sample_df['Label'].value_counts())

# --- 11. DISPLAY CENTRALITY VALUES ---
print("\n--- Centrality Summary of Final Sample ---")
# Display a statistical summary of the centrality scores
print(final_sample_df[['Label', 'degree', 'betweenness']].describe().to_string())

print("\n--- Final Sample Head ---")
# Display the first 5 rows of the final sample
print(final_sample_df[['Label', 'degree', 'betweenness']].head().to_string())


# --- 12. Save the Final Sample ---
output_filename = f"Type_{chosen_type}_Sample_{len(final_sample_df)}_Nodes.csv"
# We save the dataframe, which still has its unique integer index
final_sample_df.to_csv(output_filename, index=True, index_label='Original_Row_Index')
print(f"\nSuccessfully saved {len(final_sample_df)} node sample to '{output_filename}'")

