        nx.draw_networkx_nodes(G, pos, node_size=node_sizes, node_color="blue", alpha=0.7)
        # Draw edges
        nx.draw_networkx_edges(G, pos, width=0.2, alpha=0.4)

        # Create the label dictionary (map node index to full name)
        labels = nx.get_node_attributes(G, 'full_name')
        # Draw labels
        nx.draw_networkx_labels(G, pos, labels=labels, font_size=7, font_color="black")
        # -------------------------------------------

        plt.title(f"Graph for {graph_type_label} ({G.number_of_nodes()} nodes, {G.number_of_edges()} edges)", fontsize=20)
        plt.axis("off") # Hide the axes
        graph_filename = f"graph_{graph_type_label}.png"
