def analyze_network(df_subset, graph_type_label):
    """
    Builds a graph from a DataFrame subset using connection similarity,
    then calculates and prints all requested metrics.
    """

    # --- 1. DYNAMIC GRAPH CREATION (Connection-Similarity Logic) ---
    print("\nBuilding graph based on 'Connections' similarity...")
    G = nx.Graph()

    # Add all nodes first from the subset
    # The index (row.name) is the unique integer ID
    for i, row in df_subset.iterrows():
        G.add_node(i,
                   connections=row['Connections'],
                   full_name=row['Full Name'],
                   label=row['Label']) # Store label for potential future use

    # Compare all pairs to add edges
    subset_node_indices = list(df_subset.index) # List of unique integer indices
    for i in range(len(subset_node_indices)):
        for j in range(i + 1, len(subset_node_indices)):
            node_A_index = subset_node_indices[i]
            node_B_index = subset_node_indices[j]

            # Get connection counts using .loc on the unique integer index
            conns_A = df_subset.loc[node_A_index, 'Connections']
            conns_B = df_subset.loc[node_B_index, 'Connections']

            # This is the logic you requested
            if abs(conns_A - conns_B) <= 5:
                G.add_edge(node_A_index, node_B_index)

    print(f"Graph built: {G.number_of_nodes()} nodes, {G.number_of_edges()} edges.")

    if G.number_of_nodes() == 0 or G.number_of_edges() == 0:
        print("Graph is empty or has no edges. Cannot calculate metrics.")
        return

    # --- 2. CALCULATE & PRINT GRAPH PROPERTIES ---
    print("\n--- Graph Properties ---")

    # Density
    density = nx.density(G)
    print(f"Density: {density:.6f}")

    # Average Clustering Coefficient
    # Use warnings.catch_warnings to suppress messages on disconnected graphs
    with warnings.catch_warnings():
        warnings.simplefilter("ignore")
        avg_clustering = nx.average_clustering(G)
        print(f"Average Clustering Coefficient: {avg_clustering:.6f}")

    # Connected Components
    num_components = nx.number_connected_components(G)
    print(f"Number of Connected Components: {num_components}")

    if num_components > 1:
        try:
            largest_cc = max(nx.connected_components(G), key=len)
            print(f"  > Largest component has {len(largest_cc)} nodes ({len(largest_cc)/G.number_of_nodes():.1%} of total)")
        except ValueError:
             print("  > Could not determine largest component.")

    # --- 3. CALCULATE & PRINT CENTRALITY ---
    print("\n--- Centrality Measures ---")

    # Degree Centrality
    degree_cent = nx.degree_centrality(G)
    # Sort top 5 degree nodes
    top_5_degree = sorted(degree_cent.items(), key=lambda item: item[1], reverse=True)[:5]
    print("Top 5 Nodes by Degree Centrality:")
    for node_index, score in top_5_degree:
        full_name = G.nodes[node_index]['full_name']
        print(f"  > {full_name} (Score: {score:.4f})")

    # Betweenness Centrality
    print("\nCalculating Betweenness (may be slow)...")
    betweenness_cent = nx.betweenness_centrality(G)
    # Sort top 5 betweenness nodes
    top_5_betweenness = sorted(betweenness_cent.items(), key=lambda item: item[1], reverse=True)[:5]
    print("Top 5 Nodes by Betweenness Centrality:")
    for node_index, score in top_5_betweenness:
        full_name = G.nodes[node_index]['full_name']
        print(f"  > {full_name} (Score: {score:.4f})")

    # --- 4. CALCULATE & PRINT SIMILARITY/DISSIMILARITY ---
    print("\n--- Network Similarity ---")

    # Jaccard Similarity
    # This calculates similarity for all pairs with a non-zero neighborhood union
    jaccard_gen = nx.jaccard_coefficient(G)
    jaccard_scores = []
    for u, v, score in jaccard_gen:
        if score > 0: # Only count pairs with some similarity
            jaccard_scores.append(score)

    if not jaccard_scores:
        avg_jaccard = 0.0
    else:
        avg_jaccard = sum(jaccard_scores) / len(jaccard_scores)

    print(f"Average Jaccard Similarity (of connected pairs): {avg_jaccard:.6f}")
    print(f"Average Dissimilarity: {(1 - avg_jaccard):.6f}")

    # --- 5. VISUALIZE GRAPH ---
    print("\n--- Visualizing Graph ---")
    try:
        plt.figure(figsize=(15, 15))
        print("Drawing graph... (this may take time for large graphs)")

        pos = nx.spring_layout(G, k=0.15, iterations=20)

        # Node size based on 'Connections' attribute
        node_sizes = [10 + G.nodes[n]['connections'] for n in G.nodes()]

        # --- **NEW** Draw components separately ---
        # Draw nodes
        nx.draw_networkx_nodes(G, pos, node_size=node_sizes, node_color="blue", alpha=0.7)
        # Draw edges
        nx.draw_networkx_edges(G, pos, width=0.2, alpha=0.4)

        # Create the label dictionary (map node index to full name)
        labels = nx.get_node_attributes(G, 'full_name')
        # Draw labels
        nx.draw_networkx_labels(G, pos, labels=labels, font_size=7, font_color="black")
        # -------------------------------------------

        plt.title(f"Graph for {graph_type_label} ({G.number_of_nodes()} nodes, {G.number_of_edges()} edges)", fontsize=20)
        plt.axis("off") # Hide the axes
        graph_filename = f"graph_{graph_type_label}.png"
        plt.savefig(graph_filename)
        print(f"Graph image saved to {graph_filename}")
        plt.show()
    except Exception as e:
        print(f"Could not draw graph. Error: {e}")

