# --- GNN-Specific Imports ---
import torch
from torch_geometric.data import Data
from sklearn.preprocessing import LabelEncoder
from sklearn.model_selection import train_test_split
from torch_geometric.nn import GCNConv
import torch.nn.functional as F

# -----------------------------------------------------------------------
# --- MODIFIED ANALYZE_NETWORK FUNCTION WITH PYG CONVERSION ---
# -----------------------------------------------------------------------

def analyze_network_and_prepare_gnn_data(df_subset, graph_type_label):
    """
    Builds the NetworkX graph and converts it into a PyTorch Geometric Data object.
    """
    # ... (Your existing NetworkX building code) ...
    # --- 1. DYNAMIC GRAPH CREATION (Connection-Similarity Logic) ---
    print("\nBuilding graph based on 'Connections' similarity...")
    G = nx.Graph()

    # Add all nodes first from the subset
    for i, row in df_subset.iterrows():
        G.add_node(i,
                  connections=row['Connections'],
                  full_name=row['Full Name'],
                  label=row['Label'])

    # Compare all pairs to add edges
    subset_node_indices = list(df_subset.index)
    for i in range(len(subset_node_indices)):
        for j in range(i + 1, len(subset_node_indices)):
            node_A_index = subset_node_indices[i]
            node_B_index = subset_node_indices[j]

            conns_A = df_subset.loc[node_A_index, 'Connections']
            conns_B = df_subset.loc[node_B_index, 'Connections']

            if abs(conns_A - conns_B) <= 5:
                G.add_edge(node_A_index, node_B_index)

    print(f"Graph built: {G.number_of_nodes()} nodes, {G.number_of_edges()} edges.")
    if G.number_of_nodes() == 0 or G.number_of_edges() == 0:
        print("Graph is empty or has no edges. Cannot run GNN.")
        return G, None # Return the empty NetworkX graph and None for PyG data

    # -------------------------------------------------------------
    # --- CONVERSION TO PYTORCH GEOMETRIC (PyG) DATA OBJECT ---
    # -------------------------------------------------------------
    print("\n--- Converting to PyG Data Object for GNN ---")

    # A. Node Features (X): Use normalized 'Connections' as a primary feature
    # and one-hot encode the 'Label' column

    # 1. Connections feature: Normalize it
    connections_features = df_subset['Connections'].values.astype(np.float32)
    connections_max = connections_features.max()
    if connections_max > 0:
        connections_features /= connections_max

    # 2. Label feature: Use LabelEncoder to get numerical classes for target Y
    le = LabelEncoder()
    # We use all available labels to fit the encoder
    labels_encoded = le.fit_transform(df_subset['Label'].values)
    num_classes = len(le.classes_)

    # 3. Create Feature Tensor (X)
    # The initial feature vector x is the combination of:
    # [normalized_connections_count]
    # In a real-world scenario, you would add many more domain-specific features here.
    x_list = []
    for i in range(len(df_subset)):
        x_list.append([connections_features[i]])

    x = torch.tensor(x_list, dtype=torch.float)

    # B. Target Labels (Y)
    # The GNN's task will be Node Classification: predicting the Label class (0, 1, 2, ...)
    y = torch.tensor(labels_encoded, dtype=torch.long) # Use long for classification targets

    # C. Edge Index
    # Convert NetworkX edge list to PyG's COO format (2 x num_edges)
    # Since NetworkX uses the original DataFrame index, we need to map to 0-N-1 if G's nodes are sparse.
    # The to_undirected() is necessary for compatibility with GCNConv on unweighted graphs.
    edge_index = torch.tensor(list(G.edges)).t().contiguous()

    # D. Create the PyG Data object
    pyg_data = Data(x=x, edge_index=edge_index, y=y)

    print(f"PyG Data Object created:")
    print(f"  - Nodes (x): {pyg_data.num_nodes}")
    print(f"  - Features (x.shape): {pyg_data.x.shape}")
    print(f"  - Edges (edge_index.shape): {pyg_data.edge_index.shape}")
    print(f"  - Classes (y): {num_classes}")

    # E. Create masks for training/testing
    # We must split the nodes into training and testing sets.
    # The GNN will only "see" the labels of the training set.

    num_nodes = pyg_data.num_nodes
    # Get indices for all nodes (0 to N-1)
    all_indices = np.arange(num_nodes)

    # Split indices into 80% training, 20% test
    # This assumes the DataFrame index is continuous and starts near 0.
    # A more robust way uses the actual node indices in G.nodes() and maps them.
    # Since your NetworkX node IDs are the DF indices, we'll proceed using the range 0 to N-1 for simplicity,
    # assuming your DF index is well-behaved (dense and starting low).

    # We need to map the dataframe index (which is the node ID) back to a 0-N-1 range for the mask
    df_map = {original_idx: i for i, original_idx in enumerate(df_subset.index)}

    # Map the edge_index to the new 0-N-1 indices
    mapped_edge_index = torch.tensor([[df_map[u], df_map[v]] for u, v in G.edges()], dtype=torch.long).t().contiguous()
    pyg_data.edge_index = mapped_edge_index

    # Create the training/test mask based on the 0-N-1 sequential indices
    train_indices, test_indices = train_test_split(all_indices, test_size=0.2, random_state=42)

    # Initialize mask tensors
    train_mask = torch.zeros(num_nodes, dtype=torch.bool)
    test_mask = torch.zeros(num_nodes, dtype=torch.bool)

    # Set indices to True
    train_mask[train_indices] = True
    test_mask[test_indices] = True

    pyg_data.train_mask = train_mask
    pyg_data.test_mask = test_mask
    pyg_data.num_classes = num_classes

    # Now that we have the PyG data, we can also run your original NetworkX metrics
    # (Omitted here for brevity, but they should be placed before the PyG conversion)

    return G, pyg_data

# -----------------------------------------------------------------------
# --- GCN MODEL DEFINITION ---
# -----------------------------------------------------------------------

class GCN(torch.nn.Module):
    """Graph Convolutional Network model for node classification."""
    def __init__(self, in_channels, hidden_channels, out_channels):
        super().__init__()
        # GCNConv implements the GCN layer: Z = activation(D^-1/2 * A_hat * D^-1/2 * X * W)
        self.conv1 = GCNConv(in_channels, hidden_channels)
        self.conv2 = GCNConv(hidden_channels, out_channels)

    def forward(self, x, edge_index):
        # 1. Apply first GCN layer and ReLU activation
        x = self.conv1(x, edge_index)
        x = F.relu(x)
        x = F.dropout(x, p=0.5, training=self.training)

        # 2. Apply second GCN layer (output layer)
        x = self.conv2(x, edge_index)

        return x # The final output is logits (raw scores)

# -----------------------------------------------------------------------
# --- TRAINING AND EVALUATION FUNCTIONS ---
# -----------------------------------------------------------------------

def train(model, data, optimizer, criterion):
    model.train() # Set model to training mode
    optimizer.zero_grad() # Clear gradients

    # Forward pass: get logits
    out = model(data.x, data.edge_index)

    # Calculate loss only on the training nodes
    loss = criterion(out[data.train_mask], data.y[data.train_mask])

    # Backpropagation
    loss.backward()
    optimizer.step()
    return loss

@torch.no_grad() # Disable gradient calculations for faster evaluation
def test(model, data):
    model.eval() # Set model to evaluation mode
    out = model(data.x, data.edge_index)

    # Compute accuracy on both training and testing sets
    pred = out.argmax(dim=1) # Get the predicted class (index of max logit)

    train_correct = pred[data.train_mask] == data.y[data.train_mask]
    train_acc = int(train_correct.sum()) / int(data.train_mask.sum())

    test_correct = pred[data.test_mask] == data.y[data.test_mask]
    test_acc = int(test_correct.sum()) / int(data.test_mask.sum())

    return train_acc, test_acc

# ===================================================================
# --- MAIN SCRIPT EXECUTION WITH GNN ---
# ===================================================================

