import pandas as pd
import networkx as nx
import numpy as np
import matplotlib.pyplot as plt
import warnings
import os

# Scikit-learn imports for feature engineering
from sklearn.preprocessing import LabelEncoder, StandardScaler
from sklearn.model_selection import train_test_split
from sklearn.feature_extraction.text import TfidfVectorizer
from sklearn.decomposition import PCA

# PyTorch Geometric imports for GNN
import torch
from torch_geometric.data import Data
from torch_geometric.nn import GCNConv
import torch.nn.functional as F

# Suppress warnings for cleaner output
warnings.filterwarnings('ignore', category=UserWarning)

# -----------------------------------------------------------------------
# --- GCN MODEL DEFINITION (Capacity Increased to 64) ---
# -----------------------------------------------------------------------

class GCN(torch.nn.Module):
    """Graph Convolutional Network model for node classification."""
    def __init__(self, in_channels, hidden_channels, out_channels):
        super().__init__()
        # *** OPTIMIZATION: Hidden channels increased to 64 ***
        self.conv1 = GCNConv(in_channels, 64)
        self.conv2 = GCNConv(64, out_channels)

    def forward(self, x, edge_index):
        x = self.conv1(x, edge_index)
        x = F.relu(x)
        x = F.dropout(x, p=0.5, training=self.training)
        x = self.conv2(x, edge_index)
        return x

# -----------------------------------------------------------------------
# --- TRAINING AND EVALUATION FUNCTIONS ---
# -----------------------------------------------------------------------

def train(model, data, optimizer, criterion):
    model.train()
    optimizer.zero_grad()
    out = model(data.x, data.edge_index)
    loss = criterion(out[data.train_mask], data.y[data.train_mask])
    loss.backward()
    optimizer.step()
    return loss

@torch.no_grad()
def test(model, data):
    model.eval()
    out = model(data.x, data.edge_index)
    pred = out.argmax(dim=1)

    train_correct = pred[data.train_mask] == data.y[data.train_mask]
    train_acc = int(train_correct.sum()) / int(data.train_mask.sum())

    test_correct = pred[data.test_mask] == data.y[data.test_mask]
    test_acc = int(test_correct.sum()) / int(data.test_mask.sum())

    return train_acc, test_acc

def run_gnn_training(pyg_data, graph_type_label):
    """Initializes and runs the GCN training process."""
    print("\n--- Initializing and Training GCN Model (High Capacity) ---")

    in_channels = pyg_data.num_features
    num_classes = pyg_data.num_classes

    # Model now uses hidden_channels=64 internally
    model = GCN(in_channels=in_channels,
                hidden_channels=64,
                out_channels=num_classes)

    optimizer = torch.optim.Adam(model.parameters(), lr=0.01, weight_decay=5e-4)
    criterion = torch.nn.CrossEntropyLoss()

    best_test_acc = 0
    model_path = f'best_gcn_model_rich_features_{graph_type_label}.pt'

    for epoch in range(1, 201):
        loss = train(model, pyg_data, optimizer, criterion)
        train_acc, test_acc = test(model, pyg_data)

        if test_acc > best_test_acc:
            best_test_acc = test_acc
            torch.save(model.state_dict(), model_path)

        if epoch % 40 == 0:
            print(f'Epoch: {epoch:03d}, Loss: {loss:.4f}, Train Acc: {train_acc:.4f}, Test Acc: {test_acc:.4f}')

    # Final Evaluation
    if os.path.exists(model_path):
        model.load_state_dict(torch.load(model_path))
        final_train_acc, final_test_acc = test(model, pyg_data)

        print("\n--- Final GCN Node Classification Results (High Capacity) ---")
        print(f"Features Used: {in_channels} features (Centrality + Text + Connections)")
        print(f"Final Train Accuracy: {final_train_acc:.4f}")
        print(f"Final Test Accuracy: **{final_test_acc:.4f}** (Best was {best_test_acc:.4f})")
    else:
        print("\n--- GNN Training Failed ---")

# -----------------------------------------------------------------------
# --- GRAPH BUILDING, PREP, AND VISUALIZATION FUNCTIONS ---
# -----------------------------------------------------------------------

def build_graph_and_add_centrality(df_full):
    """
    Builds the NetworkX graph and calculates Degree/Betweenness centrality.
    """
    print("\nBuilding graph based on 'Connections' similarity and calculating centrality...")
    G = nx.Graph()

    for i, row in df_full.iterrows():
        G.add_node(i, connections=row['Connections'], full_name=row['Full Name'], label=row['Label'])

    subset_node_indices = list(df_full.index)
    for i in range(len(subset_node_indices)):
        for j in range(i + 1, len(subset_node_indices)):
            if abs(df_full.loc[subset_node_indices[i], 'Connections'] - df_full.loc[subset_node_indices[j], 'Connections']) <= 5:
                G.add_edge(subset_node_indices[i], subset_node_indices[j])

    print(f"Graph built: {G.number_of_nodes()} nodes, {G.number_of_edges()} edges.")

    if G.number_of_nodes() == 0 or G.number_of_edges() == 0:
        return G, df_full

    # Calculate Centrality
    degree_cent = nx.degree_centrality(G)

    # Safety check for Betweenness on large, dense graphs
    if G.number_of_nodes() > 1000 and nx.density(G) > 0.1:
        print("Warning: High density graph. Betweenness centrality calculation may be very slow. Using sample.")
        betweenness_cent = nx.betweenness_centrality(G, k=100, normalized=True, weight=None, endpoints=False)
        betweenness_cent.update({n: 0.0 for n in G.nodes() if n not in betweenness_cent})
    else:
        betweenness_cent = nx.betweenness_centrality(G)

    # Map scores back to the df_full
    df_full['degree'] = df_full.index.map(degree_cent).fillna(0)
    df_full['betweenness'] = df_full.index.map(betweenness_cent).fillna(0)
    print("Centrality calculation complete and added to DataFrame.")

    return G, df_full

def run_structural_analysis_and_visualization(G, graph_type_label):
    """Runs structural analysis and saves/shows the graph."""
    if G.number_of_nodes() == 0 or G.number_of_edges() == 0:
        return

    print("\n--- Graph Properties ---")
    print(f"Density: {nx.density(G):.6f}")

    with warnings.catch_warnings():
        warnings.simplefilter("ignore")
        print(f"Average Clustering Coefficient: {nx.average_clustering(G):.6f}")

    print(f"Number of Connected Components: {nx.number_connected_components(G)}")

    # Visualization
    print("\n--- Visualizing Graph ---")
    try:
        plt.figure(figsize=(15, 15))
        pos = nx.spring_layout(G, k=0.15, iterations=20)
        node_sizes = [10 + G.nodes[n]['connections'] for n in G.nodes()]

        nx.draw(G, pos=pos, node_size=node_sizes, width=0.2, with_labels=False, alpha=0.7, node_color='blue')

        plt.title(f"Graph for {graph_type_label} ({G.number_of_nodes()} nodes, {G.number_of_edges()} edges)", fontsize=20)
        graph_filename = f"graph_{graph_type_label}.png"
        plt.savefig(graph_filename)
        print(f"Graph image saved to {graph_filename}")
        plt.show()
    except Exception as e:
        print(f"Could not draw graph. Error: {e}")

def prepare_pyg_data(G, df_features, df_labels):
    """Converts the NetworkX graph and the rich feature set into a PyG Data object."""
    print("\n--- Converting Rich Features & Graph to PyG Data Object ---")

    x = torch.tensor(df_features.values, dtype=torch.float)

    le = LabelEncoder()
    labels_encoded = le.fit_transform(df_labels.values)
    num_classes = len(le.classes_)
    y = torch.tensor(labels_encoded, dtype=torch.long)

    node_map = {original_idx: i for i, original_idx in enumerate(G.nodes())}
    mapped_edges = []
    for u, v in G.edges():
        mapped_edges.append([node_map[u], node_map[v]])

    edge_index = torch.tensor(mapped_edges, dtype=torch.long).t().contiguous()

    pyg_data = Data(x=x, edge_index=edge_index, y=y)
    pyg_data.num_classes = num_classes

    num_nodes = pyg_data.num_nodes
    all_indices = np.arange(num_nodes)

    train_indices, test_indices = train_test_split(
        all_indices,
        test_size=0.2,
        random_state=42,
        stratify=labels_encoded
    )

    train_mask = torch.zeros(num_nodes, dtype=torch.bool)
    test_mask = torch.zeros(num_nodes, dtype=torch.bool)
    train_mask[train_indices] = True
    test_mask[test_indices] = True

    pyg_data.train_mask = train_mask
    pyg_data.test_mask = test_mask

    print(f"  - Final Feature Dimension: {pyg_data.x.shape[1]}")
    print(f"  - Train/Test Split: {int(train_mask.sum())} train, {int(test_mask.sum())} test nodes.")

    return pyg_data


# ===================================================================
# --- MAIN SCRIPT EXECUTION ---
# ===================================================================

file_name = 'Final Graph Nodes.xlsx'

print(f"Loading data from {file_name}...")
try:
    df = pd.read_excel(file_name)
    print("Data loaded successfully.")
except Exception as e:
    print(f"Error loading file: {e}")
    raise

# Data Cleaning
df['Full Name'] = df['Full Name'].astype(str).str.strip()
df['Connections'] = pd.to_numeric(df['Connections'], errors='coerce').fillna(0).astype(int)

# Check for 'Label'
if 'Label' not in df.columns:
    if 'Label(type of profile)' in df.columns:
        df.rename(columns={'Label(type of profile)': 'Label'}, inplace=True)
    else:
        raise ValueError("Missing 'Label' column for GNN classification.")

# 1. BUILD GRAPH AND ADD CENTRALITY SCORES
G, df = build_graph_and_add_centrality(df)

if G.number_of_nodes() == 0 or G.number_of_edges() == 0:
    print("\n--- GNN ABORTED: Graph is empty or has no edges ---")
else:
    # 2. FEATURE ENGINEERING: TEXT VECTORIZATION AND SCALING
    print("\n--- Feature Engineering: Text Vectorization and Scaling ---")

    text_cols = ['About', 'Workplace', 'Skills']
    numerical_cols = ['Connections', 'degree', 'betweenness']

    for col in text_cols:
        if col not in df.columns:
             df[col] = ''
             print(f"Warning: Column '{col}' not found, using empty string.")
        df[col] = df[col].astype(str).fillna('')

    df['combined_text'] = df[text_cols].agg(' '.join, axis=1)

    # A. TF-IDF for Text Features (max 1000 features)
    vectorizer = TfidfVectorizer(max_features=1000, stop_words='english')
    tfidf_matrix = vectorizer.fit_transform(df['combined_text']).toarray()

    # B. PCA for Dimensionality Reduction (down to 100 components)
    if tfidf_matrix.shape[1] > 100:
        print(f"Reducing {tfidf_matrix.shape[1]} text features to 100 via PCA.")
        pca = PCA(n_components=100, random_state=42)
        text_features_pca = pca.fit_transform(tfidf_matrix)
    else:
        text_features_pca = tfidf_matrix

    # C. Numerical Features Scaling (3 features: Connections, Degree, Betweenness)
    numerical_features = df[numerical_cols].values.astype(np.float32)
    scaler = StandardScaler()
    numerical_features_scaled = scaler.fit_transform(numerical_features)

    # D. Combine ALL 3 Numerical + 100 Text Features (Total ~103 features)
    X_rich_features = np.hstack([numerical_features_scaled, text_features_pca])

    df_X = pd.DataFrame(X_rich_features, index=df.index)
    df_Y = df['Label']

    # 3. GNN EXECUTION AND VISUALIZATION
    base_file_name_for_title = file_name.replace('.xlsx', '').replace(' ', '_')
    pyg_data = prepare_pyg_data(G, df_X, df_Y)
    run_gnn_training(pyg_data, base_file_name_for_title)

    # Run structural analysis and visualization
    run_structural_analysis_and_visualization(G, base_file_name_for_title)

print("\n--- Process Complete ---")

import pandas as pd
import networkx as nx
import numpy as np
import matplotlib.pyplot as plt
import warnings
import os
import torch

# Scikit-learn imports for feature engineering
from sklearn.preprocessing import StandardScaler
from sklearn.model_selection import train_test_split
from sklearn.feature_extraction.text import TfidfVectorizer
from sklearn.decomposition import PCA
from sklearn.metrics import roc_auc_score

# PyTorch Geometric imports for GNN (assuming installation is done in Colab)
from torch_geometric.data import Data
from torch_geometric.nn import GCNConv
import torch.nn.functional as F

# Suppress warnings
warnings.filterwarnings('ignore', category=UserWarning)

# --- Hyperparameter Definition ---
HIDDEN_CHANNELS = 64
EMBEDDING_DIM = 32 # Final dimension of the node embedding (Z)
EPOCHS = 200

# -----------------------------------------------------------------------
# --- GCN ENCODER MODEL FOR LINK PREDICTION ---
# -----------------------------------------------------------------------

class GCNEncoder(torch.nn.Module):
    """GCN to generate node embeddings Z."""
    def __init__(self, in_channels, hidden_channels, out_channels):
        super().__init__()
        self.conv1 = GCNConv(in_channels, hidden_channels)
        self.conv2 = GCNConv(hidden_channels, out_channels)

    def forward(self, x, edge_index):
        x = self.conv1(x, edge_index)
        x = F.relu(x)
        x = F.dropout(x, p=0.5, training=self.training)
        x = self.conv2(x, edge_index)
        return x # Z

# -----------------------------------------------------------------------
# --- LINK PREDICTION TRAINING AND EVALUATION FUNCTIONS ---
# -----------------------------------------------------------------------

def get_link_prediction_loss(z, pos_edge_index, neg_edge_index):
    """Calculates Binary Cross-Entropy loss for link prediction."""
    edge_index = torch.cat([pos_edge_index, neg_edge_index], dim=-1)
    target = torch.cat([torch.ones(pos_edge_index.size(1)), torch.zeros(neg_edge_index.size(1))], dim=0).to(z.device)

    # Simple dot product decoder
    row, col = edge_index
    score = (z[row] * z[col]).sum(dim=-1)

    return F.binary_cross_entropy_with_logits(score, target)

@torch.no_grad()
def evaluate_link_prediction(model, z, pos_edge_index, neg_edge_index):
    """Calculates AUC-ROC for link prediction evaluation."""
    model.eval()

    edge_index = torch.cat([pos_edge_index, neg_edge_index], dim=-1)
    target = torch.cat([torch.ones(pos_edge_index.size(1)), torch.zeros(neg_edge_index.size(1))], dim=0).to(z.device)

    row, col = edge_index
    score = (z[row] * z[col]).sum(dim=-1)

    # Convert logits (scores) to probabilities for AUC-ROC
    prob = torch.sigmoid(score).cpu().numpy()
    target = target.cpu().numpy()

    # AUC-ROC is the standard metric for link prediction/recommendation
    return roc_auc_score(target, prob)

def train_link_prediction(model, data, optimizer, train_pos_edge, val_pos_edge, val_neg_edge):
    """Training loop for Link Prediction."""

    # Generate dynamic negative samples for the training set
    neg_sampler = nx.non_edges(data.G_nx)
    neg_edges_list = list(neg_sampler)

    if not neg_edges_list: # Check if graph is fully connected
        return 0.0, 0.5

    num_neg_edges = min(train_pos_edge.size(1), len(neg_edges_list))

    np.random.shuffle(neg_edges_list)
    train_neg_edges_list = neg_edges_list[:num_neg_edges]
    train_neg_edge = torch.tensor(train_neg_edges_list, dtype=torch.long).t().contiguous()

    model.train()
    optimizer.zero_grad()

    z = model(data.x, data.full_edge_index)
    loss = get_link_prediction_loss(z, train_pos_edge, train_neg_edge)
    loss.backward()
    optimizer.step()

    val_auc = evaluate_link_prediction(model, z, val_pos_edge, val_neg_edge)

    return loss.item(), val_auc

# -----------------------------------------------------------------------
# --- GRAPH BUILDING AND FEATURE PREPARATION ---
# -----------------------------------------------------------------------

def build_graph_and_prepare_features(df_full):
    """
    Builds the NetworkX graph, calculates centrality, and prepares the rich feature matrix (X).
    """
    # 1. GRAPH BUILDING & CENTRALITY
    print("\nBuilding graph based on 'Connections' similarity and calculating centrality...")
    G = nx.Graph()
    for i, row in df_full.iterrows():
        G.add_node(i, connections=row['Connections'], full_name=row['Full Name'], label=row['Label'])

    subset_node_indices = list(df_full.index)
    for i in range(len(subset_node_indices)):
        for j in range(i + 1, len(subset_node_indices)):
            if abs(df_full.loc[subset_node_indices[i], 'Connections'] - df_full.loc[subset_node_indices[j], 'Connections']) <= 5:
                G.add_edge(subset_node_indices[i], subset_node_indices[j])

    degree_cent = nx.degree_centrality(G)
    betweenness_cent = nx.betweenness_centrality(G)

    df_full['degree'] = df_full.index.map(degree_cent).fillna(0)
    df_full['betweenness'] = df_full.index.map(betweenness_cent).fillna(0)
    print(f"Graph built: {G.number_of_nodes()} nodes, {G.number_of_edges()} edges. Centrality added.")

    # 2. FEATURE ENGINEERING (Combined Text + Numerical)
    print("--- Feature Engineering: Combining all text and numerical features ---")

    # Include 'Interests' and other text fields
    text_cols = ['About', 'Workplace', 'Skills', 'Interests']
    numerical_cols = ['Connections', 'degree', 'betweenness']

    for col in text_cols:
        if col not in df_full.columns:
             df_full[col] = ''
        df_full[col] = df_full[col].astype(str).fillna('')

    df_full['combined_text'] = df_full[text_cols].agg(' '.join, axis=1)

    # TF-IDF (max 1000 features) -> PCA (100 components)
    vectorizer = TfidfVectorizer(max_features=1000, stop_words='english')
    tfidf_matrix = vectorizer.fit_transform(df_full['combined_text']).toarray()

    pca = PCA(n_components=100, random_state=42)
    text_features_pca = pca.fit_transform(tfidf_matrix)

    # Scale Numerical Features (3 features)
    numerical_features = df_full[numerical_cols].values.astype(np.float32)
    scaler = StandardScaler()
    numerical_features_scaled = scaler.fit_transform(numerical_features)

    # Combine ALL features (Total 3 + 100 = 103 features)
    X_rich_features = np.hstack([numerical_features_scaled, text_features_pca])

    df_X = pd.DataFrame(X_rich_features, index=df_full.index)

    return G, df_X

def prepare_link_prediction_data(G, df_X):
    """
    Prepares PyG Data object for Link Prediction, splitting edges into train/val.
    """
    print("\n--- Preparing PyG Data for Link Prediction ---")

    # A. Map NetworkX indices to dense 0-N-1 indices
    node_map = {original_idx: i for i, original_idx in enumerate(G.nodes())}

    # B. Get all edges (positive samples)
    all_edges_list = [(node_map[u], node_map[v]) for u, v in G.edges()]
    all_edges = torch.tensor(all_edges_list, dtype=torch.long).t().contiguous()

    # C. Split edges into training and validation sets (90% train, 10% val)
    num_edges = all_edges.size(1)
    perm = torch.randperm(num_edges)

    val_size = int(0.1 * num_edges)
    train_size = num_edges - val_size

    train_pos_edge = all_edges[:, perm[:train_size]]
    val_pos_edge = all_edges[:, perm[train_size:]]

    # D. Generate Negative Samples for Validation (Non-Existent Edges)
    num_neg_edges = val_size
    G_dense = nx.Graph()
    G_dense.add_edges_from(all_edges.t().tolist()) # Use all edges for the base graph

    val_neg_edges_list = list(nx.non_edges(G_dense))

    if len(val_neg_edges_list) < num_neg_edges:
        np.random.shuffle(val_neg_edges_list)
        val_neg_edge = torch.tensor(val_neg_edges_list, dtype=torch.long).t().contiguous()
    else:
        np.random.shuffle(val_neg_edges_list)
        val_neg_edge = torch.tensor(val_neg_edges_list[:num_neg_edges], dtype=torch.long).t().contiguous()

    print(f"  - Total Edges: {num_edges}")
    print(f"  - Train Edges (Pos): {train_pos_edge.size(1)}")
    print(f"  - Val Edges (Pos): {val_pos_edge.size(1)}")
    print(f"  - Val Edges (Neg): {val_neg_edge.size(1)}")

    # E. Create PyG Data object
    pyg_data = Data(x=torch.tensor(df_X.values, dtype=torch.float),
                    full_edge_index=all_edges)
    pyg_data.G_nx = G_dense # Used for dynamic negative sampling

    return pyg_data, train_pos_edge, val_pos_edge, val_neg_edge

# -----------------------------------------------------------------------
# --- MAIN EXECUTION FOR LINK PREDICTION ---
# -----------------------------------------------------------------------

file_name = 'Final Graph Nodes.xlsx'
base_file_name_for_title = file_name.replace('.xlsx', '').replace(' ', '_')

print(f"Loading data from {file_name}...")
try:
    df = pd.read_excel(file_name)
    df['Full Name'] = df['Full Name'].astype(str).str.strip()
    df['Connections'] = pd.to_numeric(df['Connections'], errors='coerce').fillna(0).astype(int)

    if 'Label' not in df.columns and 'Label(type of profile)' in df.columns:
        df.rename(columns={'Label(type of profile)': 'Label'}, inplace=True)

    # Ensure 'Interests' column exists for feature extraction
    if 'Interests' not in df.columns:
        print("Warning: 'Interests' column not found. Creating a placeholder.")
        df['Interests'] = ''

except Exception as e:
    print(f"Error loading file: {e}")
    raise

# 1. BUILD GRAPH AND PREPARE RICH FEATURES
G, df_X = build_graph_and_prepare_features(df)

if G.number_of_nodes() == 0 or G.number_of_edges() == 0:
    print("\n--- LINK PREDICTION ABORTED: Graph is empty or has no edges ---")
else:
    # 2. PREPARE LINK PREDICTION DATA
    pyg_data, train_pos_edge, val_pos_edge, val_neg_edge = prepare_link_prediction_data(G, df_X)

    # 3. INITIALIZE MODEL
    print("\n--- Initializing Link Prediction Model ---")
    in_channels = pyg_data.x.size(1)
    model = GCNEncoder(in_channels=in_channels,
                       hidden_channels=HIDDEN_CHANNELS,
                       out_channels=EMBEDDING_DIM)

    optimizer = torch.optim.Adam(model.parameters(), lr=0.01)

    # 4. TRAINING LOOP
    print(f"\n--- Starting Link Prediction Training ({EMBEDDING_DIM}D Embeddings) ---")
    best_val_auc = 0

    for epoch in range(1, EPOCHS + 1):
        loss, val_auc = train_link_prediction(model, pyg_data, optimizer, train_pos_edge, val_pos_edge, val_neg_edge)

        if val_auc > best_val_auc:
            best_val_auc = val_auc
            torch.save(model.state_dict(), f'best_link_predictor_{base_file_name_for_title}.pt')

        if epoch % 40 == 0:
            print(f'Epoch: {epoch:03d}, Loss: {loss:.4f}, Val AUC: {val_auc:.4f}')

    # 5. FINAL EVALUATION AND RECOMMENDATION GENERATION
    print("\n--- Final Link Prediction Evaluation ---")
    model.load_state_dict(torch.load(f'best_link_predictor_{base_file_name_for_title}.pt'))

    model.eval()
    final_embeddings = model(pyg_data.x, pyg_data.full_edge_index)

    print(f"Best Validation AUC (Recommendation Performance): **{best_val_auc:.4f}** (Closer to 1.0 is better)")

    # --- Recommendation Logic ---
    print("\n--- Generating Top 5 Career Recommendations ---")

    # Identify the index to name mapping
    name_map_dense_to_orig = {i: original_idx for i, original_idx in enumerate(G.nodes())}

    # Find Job Seekers and Job Providers (0-N-1 dense indices)
    job_seekers_df = df[df['Label'] == 'Job Seeker']
    job_providers_df = df[df['Label'] == 'Job Provider']

    if not job_seekers_df.empty and not job_providers_df.empty:
        node_map = {original_idx: i for i, original_idx in enumerate(G.nodes())}
        dense_seeker_indices = [node_map[i] for i in job_seekers_df.index if i in node_map]
        dense_provider_indices = [node_map[i] for i in job_providers_df.index if i in node_map]

        if dense_seeker_indices and dense_provider_indices:
            # Select the first Job Seeker for a sample recommendation
            sample_seeker_orig_index = job_seekers_df.iloc[0].name
            sample_seeker_dense_index = node_map[sample_seeker_orig_index]

            seeker_embedding = final_embeddings[sample_seeker_dense_index]

            scores = {}
            for provider_dense_index in dense_provider_indices:
                provider_embedding = final_embeddings[provider_dense_index]
                link_score = torch.dot(seeker_embedding, provider_embedding).item()

                provider_orig_index = name_map_dense_to_orig[provider_dense_index]
                provider_name = df.loc[provider_orig_index, 'Full Name']
                scores[provider_name] = link_score

            top_recommendations = sorted(scores.items(), key=lambda item: item[1], reverse=True)[:5]

            print(f"\nTop 5 Career Recommendations (Job Providers) for Job Seeker: {df.loc[sample_seeker_orig_index, 'Full Name']} (based on Interests):")
            for rank, (name, score) in enumerate(top_recommendations):
                print(f"  {rank + 1}. {name} (Link Score: {score:.4f})")
        else:
            print("Could not map all Job Seekers/Providers to graph nodes.")
    else:
        print("Cannot generate recommendations: Ensure 'Job Seeker' and 'Job Provider' labels exist in the dataset.")

print("\n--- Process Complete ---")

import pandas as pd
import networkx as nx
import numpy as np
import matplotlib.pyplot as plt
import warnings
import os
import torch

# Scikit-learn imports for feature engineering
from sklearn.preprocessing import StandardScaler
from sklearn.model_selection import train_test_split
from sklearn.feature_extraction.text import TfidfVectorizer
from sklearn.decomposition import PCA
from sklearn.metrics import roc_auc_score

# PyTorch Geometric imports for GNN
from torch_geometric.data import Data
from torch_geometric.nn import GCNConv
import torch.nn.functional as F

# Suppress warnings
warnings.filterwarnings('ignore', category=UserWarning)

# --- Hyperparameter Definition ---
HIDDEN_CHANNELS = 64
EMBEDDING_DIM = 32
EPOCHS = 200

# -----------------------------------------------------------------------
# --- GCN ENCODER MODEL FOR LINK PREDICTION ---
# -----------------------------------------------------------------------

class GCNEncoder(torch.nn.Module):
    """GCN to generate node embeddings Z."""
    def __init__(self, in_channels, hidden_channels, out_channels):
        super().__init__()
        # Hidden layer capacity set to 64
        self.conv1 = GCNConv(in_channels, hidden_channels)
        self.conv2 = GCNConv(hidden_channels, out_channels)

    def forward(self, x, edge_index):
        x = self.conv1(x, edge_index)
        x = F.relu(x)
        x = F.dropout(x, p=0.5, training=self.training)
        x = self.conv2(x, edge_index)
        return x # Z

# -----------------------------------------------------------------------
# --- LINK PREDICTION TRAINING AND EVALUATION FUNCTIONS ---
# -----------------------------------------------------------------------

def get_link_prediction_loss(z, pos_edge_index, neg_edge_index):
    """Calculates Binary Cross-Entropy loss for link prediction."""
    edge_index = torch.cat([pos_edge_index, neg_edge_index], dim=-1)
    target = torch.cat([torch.ones(pos_edge_index.size(1)), torch.zeros(neg_edge_index.size(1))], dim=0).to(z.device)

    # Simple dot product decoder
    row, col = edge_index
    score = (z[row] * z[col]).sum(dim=-1)

    return F.binary_cross_entropy_with_logits(score, target)

@torch.no_grad()
def evaluate_link_prediction(model, z, pos_edge_index, neg_edge_index):
    """Calculates AUC-ROC for link prediction evaluation."""
    model.eval()

    edge_index = torch.cat([pos_edge_index, neg_edge_index], dim=-1)
    target = torch.cat([torch.ones(pos_edge_index.size(1)), torch.zeros(neg_edge_index.size(1))], dim=0).to(z.device)

    row, col = edge_index
    score = (z[row] * z[col]).sum(dim=-1)

    prob = torch.sigmoid(score).cpu().numpy()
    target = target.cpu().numpy()

    return roc_auc_score(target, prob)

def train_link_prediction(model, data, optimizer, train_pos_edge, val_pos_edge, val_neg_edge):
    """Training loop for Link Prediction."""

    neg_sampler = nx.non_edges(data.G_nx)
    neg_edges_list = list(neg_sampler)

    if not neg_edges_list:
        return 0.0, 0.5

    num_neg_edges = min(train_pos_edge.size(1), len(neg_edges_list))

    np.random.shuffle(neg_edges_list)
    train_neg_edges_list = neg_edges_list[:num_neg_edges]
    train_neg_edge = torch.tensor(train_neg_edges_list, dtype=torch.long).t().contiguous()

    model.train()
    optimizer.zero_grad()

    # *** FIX: Use pyg_data.full_edge_index ***
    z = model(data.x, data.full_edge_index)

    loss = get_link_prediction_loss(z, train_pos_edge, train_neg_edge)
    loss.backward()
    optimizer.step()

    val_auc = evaluate_link_prediction(model, z, val_pos_edge, val_neg_edge)

    return loss.item(), val_auc

# -----------------------------------------------------------------------
# --- GRAPH BUILDING AND FEATURE PREPARATION ---
# -----------------------------------------------------------------------

def build_graph_and_prepare_features(df_full):
    """
    Builds the NetworkX graph, calculates centrality, and prepares the rich feature matrix (X).
    """
    print("\nBuilding graph based on 'Connections' similarity and calculating centrality...")
    G = nx.Graph()
    for i, row in df_full.iterrows():
        G.add_node(i, connections=row['Connections'], full_name=row['Full Name'], label=row['Label'])

    subset_node_indices = list(df_full.index)
    for i in range(len(subset_node_indices)):
        for j in range(i + 1, len(subset_node_indices)):
            if abs(df_full.loc[subset_node_indices[i], 'Connections'] - df_full.loc[subset_node_indices[j], 'Connections']) <= 5:
                G.add_edge(subset_node_indices[i], subset_node_indices[j])

    degree_cent = nx.degree_centrality(G)
    betweenness_cent = nx.betweenness_centrality(G)

    df_full['degree'] = df_full.index.map(degree_cent).fillna(0)
    df_full['betweenness'] = df_full.index.map(betweenness_cent).fillna(0)
    print(f"Graph built: {G.number_of_nodes()} nodes, {G.number_of_edges()} edges. Centrality added.")

    # 2. FEATURE ENGINEERING (Combined Text + Numerical)
    print("--- Feature Engineering: Combining all text and numerical features ---")

    text_cols = ['About', 'Workplace', 'Skills', 'Interests']
    numerical_cols = ['Connections', 'degree', 'betweenness']

    for col in text_cols:
        if col not in df_full.columns:
             df_full[col] = ''
        df_full[col] = df_full[col].astype(str).fillna('')

    df_full['combined_text'] = df_full[text_cols].agg(' '.join, axis=1)

    # TF-IDF (max 1000 features) -> PCA (100 components)
    vectorizer = TfidfVectorizer(max_features=1000, stop_words='english')
    tfidf_matrix = vectorizer.fit_transform(df_full['combined_text']).toarray()

    pca = PCA(n_components=100, random_state=42)
    text_features_pca = pca.fit_transform(tfidf_matrix)

    # Scale Numerical Features (3 features)
    numerical_features = df_full[numerical_cols].values.astype(np.float32)
    scaler = StandardScaler()
    numerical_features_scaled = scaler.fit_transform(numerical_features)

    # Combine ALL features (Total 3 + 100 = 103 features)
    X_rich_features = np.hstack([numerical_features_scaled, text_features_pca])

    df_X = pd.DataFrame(X_rich_features, index=df_full.index)

    return G, df_X

def prepare_link_prediction_data(G, df_X):
    """
    Prepares PyG Data object for Link Prediction, splitting edges into train/val.
    """
    print("\n--- Preparing PyG Data for Link Prediction ---")

    node_map = {original_idx: i for i, original_idx in enumerate(G.nodes())}

    all_edges_list = [(node_map[u], node_map[v]) for u, v in G.edges()]
    all_edges = torch.tensor(all_edges_list, dtype=torch.long).t().contiguous()

    num_edges = all_edges.size(1)
    perm = torch.randperm(num_edges)

    val_size = int(0.1 * num_edges)
    train_size = num_edges - val_size

    train_pos_edge = all_edges[:, perm[:train_size]]
    val_pos_edge = all_edges[:, perm[train_size:]]

    num_neg_edges = val_size
    G_dense = nx.Graph()
    G_dense.add_edges_from(all_edges.t().tolist())

    val_neg_edges_list = list(nx.non_edges(G_dense))

    if len(val_neg_edges_list) < num_neg_edges:
        np.random.shuffle(val_neg_edges_list)
        val_neg_edge = torch.tensor(val_neg_edges_list, dtype=torch.long).t().contiguous()
    else:
        np.random.shuffle(val_neg_edges_list)
        val_neg_edge = torch.tensor(val_neg_edges_list[:num_neg_edges], dtype=torch.long).t().contiguous()

    print(f"  - Total Edges: {num_edges}")
    print(f"  - Train Edges (Pos): {train_pos_edge.size(1)}")
    print(f"  - Val Edges (Pos): {val_pos_edge.size(1)}")
    print(f"  - Val Edges (Neg): {val_neg_edge.size(1)}")

    pyg_data = Data(x=torch.tensor(df_X.values, dtype=torch.float),
                    full_edge_index=all_edges)
    pyg_data.G_nx = G_dense

    return pyg_data, train_pos_edge, val_pos_edge, val_neg_edge

def run_structural_analysis_and_visualization(G, graph_type_label):
    """Runs structural analysis and saves/shows the graph."""
    if G.number_of_nodes() == 0 or G.number_of_edges() == 0:
        return

    print("\n--- Graph Properties ---")
    print(f"Density: {nx.density(G):.6f}")

    with warnings.catch_warnings():
        warnings.simplefilter("ignore")
        print(f"Average Clustering Coefficient: {nx.average_clustering(G):.6f}")

    print(f"Number of Connected Components: {nx.number_connected_components(G)}")

    # Visualization
    print("\n--- Visualizing Graph ---")
    try:
        plt.figure(figsize=(15, 15))
        pos = nx.spring_layout(G, k=0.15, iterations=20)
        node_sizes = [10 + G.nodes[n]['connections'] for n in G.nodes()]

        nx.draw(G, pos=pos, node_size=node_sizes, width=0.2, with_labels=False, alpha=0.7, node_color='blue')

        plt.title(f"Graph for {graph_type_label} ({G.number_of_nodes()} nodes, {G.number_of_edges()} edges)", fontsize=20)
        graph_filename = f"graph_{graph_type_label}.png"
        plt.savefig(graph_filename)
        print(f"Graph image saved to {graph_filename}")
        plt.show()
    except Exception as e:
        print(f"Could not draw graph. Error: {e}")

# -----------------------------------------------------------------------
# --- MAIN EXECUTION FOR LINK PREDICTION ---
# -----------------------------------------------------------------------

file_name = 'Final Graph Nodes.xlsx'
base_file_name_for_title = file_name.replace('.xlsx', '').replace(' ', '_')

print(f"Loading data from {file_name}...")
try:
    df = pd.read_excel(file_name)
    df['Full Name'] = df['Full Name'].astype(str).str.strip()
    df['Connections'] = pd.to_numeric(df['Connections'], errors='coerce').fillna(0).astype(int)

    if 'Label' not in df.columns and 'Label(type of profile)' in df.columns:
        df.rename(columns={'Label(type of profile)': 'Label'}, inplace=True)

    if 'Interests' not in df.columns:
        print("Warning: 'Interests' column not found. Creating a placeholder.")
        df['Interests'] = ''

except Exception as e:
    print(f"Error loading file: {e}")
    raise

# 1. BUILD GRAPH AND PREPARE RICH FEATURES
G, df_X = build_graph_and_prepare_features(df)

if G.number_of_nodes() == 0 or G.number_of_edges() == 0:
    print("\n--- LINK PREDICTION ABORTED: Graph is empty or has no edges ---")
else:
    # 2. PREPARE LINK PREDICTION DATA
    pyg_data, train_pos_edge, val_pos_edge, val_neg_edge = prepare_link_prediction_data(G, df_X)

    # 3. INITIALIZE MODEL
    print("\n--- Initializing Link Prediction Model ---")
    in_channels = pyg_data.x.size(1)
    model = GCNEncoder(in_channels=in_channels,
                       hidden_channels=HIDDEN_CHANNELS,
                       out_channels=EMBEDDING_DIM)

    optimizer = torch.optim.Adam(model.parameters(), lr=0.01)

    # 4. TRAINING LOOP
    print(f"\n--- Starting Link Prediction Training ({EMBEDDING_DIM}D Embeddings) ---")
    best_val_auc = 0

    for epoch in range(1, EPOCHS + 1):
        loss, val_auc = train_link_prediction(model, pyg_data, optimizer, train_pos_edge, val_pos_edge, val_neg_edge)

        if val_auc > best_val_auc:
            best_val_auc = val_auc
            torch.save(model.state_dict(), f'best_link_predictor_{base_file_name_for_title}.pt')

        if epoch % 40 == 0:
            print(f'Epoch: {epoch:03d}, Loss: {loss:.4f}, Val AUC: {val_auc:.4f}')

    # 5. FINAL EVALUATION AND RECOMMENDATION GENERATION
    print("\n--- Final Link Prediction Evaluation ---")
    model.load_state_dict(torch.load(f'best_link_predictor_{base_file_name_for_title}.pt'))

    model.eval()
    # *** FIXED: Corrected variable name to pyg_data.full_edge_index ***
    final_embeddings = model(pyg_data.x, pyg_data.full_edge_index)

    print(f"Best Validation AUC (Recommendation Performance): **{best_val_auc:.4f}** (Closer to 1.0 is better)")

    # --- Recommendation Logic ---
    print("\n--- Generating Top 5 Career Recommendations ---")

    name_map_dense_to_orig = {i: original_idx for i, original_idx in enumerate(G.nodes())}
    job_seekers_df = df[df['Label'] == 'Job Seeker']
    job_providers_df = df[df['Label'] == 'Job Provider']

    if not job_seekers_df.empty and not job_providers_df.empty:
        node_map = {original_idx: i for i, original_idx in enumerate(G.nodes())}
        dense_seeker_indices = [node_map[i] for i in job_seekers_df.index if i in node_map]
        dense_provider_indices = [node_map[i] for i in job_providers_df.index if i in node_map]

        if dense_seeker_indices and dense_provider_indices:
            sample_seeker_orig_index = job_seekers_df.iloc[0].name
            sample_seeker_dense_index = node_map[sample_seeker_orig_index]

            seeker_embedding = final_embeddings[sample_seeker_dense_index]

            scores = {}
            for provider_dense_index in dense_provider_indices:
                provider_embedding = final_embeddings[provider_dense_index]
                link_score = torch.dot(seeker_embedding, provider_embedding).item()

                provider_orig_index = name_map_dense_to_orig[provider_dense_index]
                provider_name = df.loc[provider_orig_index, 'Full Name']
                scores[provider_name] = link_score

            top_recommendations = sorted(scores.items(), key=lambda item: item[1], reverse=True)[:5]

            print(f"\nTop 5 Career Recommendations (Job Providers) for Job Seeker: {df.loc[sample_seeker_orig_index, 'Full Name']} (based on Interests):")
            for rank, (name, score) in enumerate(top_recommendations):
                print(f"  {rank + 1}. {name} (Link Score: {score:.4f})")
        else:
            print("Could not map all Job Seekers/Providers to graph nodes.")
    else:
        print("Cannot generate recommendations: Ensure 'Job Seeker' and 'Job Provider' labels exist in the dataset.")

    # 6. RUN VISUALIZATION
    run_structural_analysis_and_visualization(G, base_file_name_for_title)

print("\n--- Process Complete ---")

