import pandas as pd
import networkx as nx
import numpy as np
import warnings
import os
import torch
import sys # For input handling

# Scikit-learn imports (for feature regeneration)
from sklearn.preprocessing import StandardScaler
from sklearn.feature_extraction.text import TfidfVectorizer
from sklearn.decomposition import PCA
from sklearn.preprocessing import LabelEncoder

# PyTorch Geometric imports (must be installed)
try:
    from torch_geometric.data import Data
    from torch_geometric.nn import SAGEConv
    import torch.nn.functional as F
except ImportError:
    print("--- FATAL ERROR ---")
    print("PyTorch Geometric not found. Please ensure it is installed.")
    sys.exit(1)


warnings.filterwarnings('ignore', category=UserWarning)

# --- HYPERPARAMETERS & FILE PATHS (MUST MATCH TRAINING) ---
HIDDEN_CHANNELS = 64
EMBEDDING_DIM = 32
FILE_NAME = 'Final Graph Nodes.xlsx'
BASE_FILE_NAME = FILE_NAME.replace('.xlsx', '').replace(' ', '_')
MODEL_PATH = f'best_link_predictor_{BASE_FILE_NAME}.pt'
# -----------------------------------------------------------------------


# -----------------------------------------------------------------------
# --- GRAPHSAGE ENCODER MODEL (Must match structure of the trained model) ---
# -----------------------------------------------------------------------

class GraphSAGEEncoder(torch.nn.Module):
    """GraphSAGE Encoder for generating Z embeddings."""
    def __init__(self, in_channels, hidden_channels, out_channels):
        super().__init__()
        self.conv1 = SAGEConv(in_channels, hidden_channels)
        self.conv2 = SAGEConv(hidden_channels, out_channels)

    def forward(self, x, edge_index):
        x = self.conv1(x, edge_index)
        x = F.relu(x)
        x = F.dropout(x, p=0.5, training=self.training)
        x = self.conv2(x, edge_index)
        return x # Z

# -----------------------------------------------------------------------
# --- CORE DATA & FEATURE REGENERATION ---
# -----------------------------------------------------------------------

def load_data_and_regenerate_features(file_name):
    """Loads data and regenerates the graph, centrality, and feature matrix X."""
    print(f"Loading and processing data from {file_name}...")
    try:
        df = pd.read_excel(file_name)
    except Exception as e:
        print(f"Error loading file: {e}")
        return None, None, None

    # Data Cleaning and Labeling
    df['Full Name'] = df['Full Name'].astype(str).str.strip()
    df['Connections'] = pd.to_numeric(df['Connections'], errors='coerce').fillna(0).astype(int)
    if 'Label' not in df.columns and 'Label(type of profile)' in df.columns:
        df.rename(columns={'Label(type of profile)': 'Label'}, inplace=True)
    if 'Interests' not in df.columns: df['Interests'] = ''

    # 1. GRAPH BUILDING & CENTRALITY (REQUIRED for centrality features and node mapping)
    G = nx.Graph()
    for i, row in df.iterrows():
        G.add_node(i, connections=row['Connections'], full_name=row['Full Name'], label=row['Label'])

    subset_node_indices = list(df.index)
    for i in range(len(subset_node_indices)):
        for j in range(i + 1, len(subset_node_indices)):
            if abs(df.loc[subset_node_indices[i], 'Connections'] - df.loc[subset_node_indices[j], 'Connections']) <= 5:
                G.add_edge(subset_node_indices[i], subset_node_indices[j])

    degree_cent = nx.degree_centrality(G)
    betweenness_cent = nx.betweenness_centrality(G)
    df['degree'] = df.index.map(degree_cent).fillna(0)
    df['betweenness'] = df.index.map(betweenness_cent).fillna(0)

    # 2. FEATURE ENGINEERING (Must be IDENTICAL to training)
    text_cols = ['About', 'Workplace', 'Skills', 'Interests']
    numerical_cols = ['Connections', 'degree', 'betweenness']

    for col in text_cols: df[col] = df[col].astype(str).fillna('')
    df['combined_text'] = df[text_cols].agg(' '.join, axis=1)

    vectorizer = TfidfVectorizer(max_features=1000, stop_words='english')
    tfidf_matrix = vectorizer.fit_transform(df['combined_text']).toarray()

    pca = PCA(n_components=100, random_state=42)
    text_features_pca = pca.fit_transform(tfidf_matrix)

    numerical_features = df[numerical_cols].values.astype(np.float32)
    scaler = StandardScaler()
    numerical_features_scaled = scaler.fit_transform(numerical_features)

    X_rich_features = np.hstack([numerical_features_scaled, text_features_pca])
    df_X = pd.DataFrame(X_rich_features, index=df.index)

    return df, df_X, G

# -----------------------------------------------------------------------
# --- MAIN INFERENCE SCRIPT ---
# -----------------------------------------------------------------------

def run_recommendation_system():
    # Load and regenerate features/graph
    df, df_X, G = load_data_and_regenerate_features(FILE_NAME)

    if df is None: return

    # Check for trained model
    if not os.path.exists(MODEL_PATH):
        print("\n--- FATAL ERROR: MODEL NOT FOUND ---")
        print(f"Cannot run recommendation. The trained model weights must be present at: {MODEL_PATH}")
        print("Please ensure you successfully ran the GraphSAGE training step previously.")
        return

    # 1. Setup PyG Data structure for inference
    node_map = {original_idx: i for i, original_idx in enumerate(G.nodes())}
    all_edges_list = [(node_map[u], node_map[v]) for u, v in G.edges()]
    pyg_edge_index = torch.tensor(all_edges_list, dtype=torch.long).t().contiguous()

    # Create the node feature tensor
    x_tensor = torch.tensor(df_X.values, dtype=torch.float)

    # 2. Initialize and Load Model Weights
    in_channels = df_X.shape[1]
    model = GraphSAGEEncoder(in_channels=in_channels,
                             hidden_channels=HIDDEN_CHANNELS,
                             out_channels=EMBEDDING_DIM)

    model.load_state_dict(torch.load(MODEL_PATH))
    model.eval()

    # 3. Generate FINAL Embeddings (Z)
    print("\nGenerating final GraphSAGE embeddings for all nodes...")
    with torch.no_grad():
        final_embeddings = model(x_tensor, pyg_edge_index)

    # 4. Interactive Input Loop
    print("\n--- INTERACTIVE CAREER RECOMMENDATION SYSTEM ---")
    print("Available profile types: Job Seeker, Job Provider, Other")

    # Filter for Job Seekers
    job_seekers = df[df['Label'] == 'Job Seeker']['Full Name'].tolist()
    if not job_seekers:
        print("No 'Job Seeker' profiles found in the dataset.")
        return

    while True:
        seeker_name = input("\nEnter the FULL NAME of the Job Seeker (or type 'quit'): ").strip()
        if seeker_name.lower() == 'quit':
            break

        # A. Find the seeker's original index and check if valid
        try:
            seeker_df_row = df[df['Full Name'] == seeker_name]
            if seeker_df_row.empty:
                print(f"Error: Profile '{seeker_name}' not found or is not a Job Seeker.")
                continue

            seeker_orig_index = seeker_df_row.index[0]
            seeker_label = seeker_df_row['Label'].iloc[0]

            if seeker_label != 'Job Seeker':
                print(f"Error: '{seeker_name}' is a '{seeker_label}', not a Job Seeker.")
                continue

            seeker_dense_index = node_map.get(seeker_orig_index)
            if seeker_dense_index is None:
                print("Error: Seeker node not found in the graph map.")
                continue

        except Exception:
            print("Error processing input. Please check the exact name.")
            continue

        # B. Get seeker embedding and identify all providers
        seeker_embedding = final_embeddings[seeker_dense_index]
        job_providers_df = df[df['Label'] == 'Job Provider']

        scores = {}
        for provider_orig_index, provider_row in job_providers_df.iterrows():
            provider_dense_index = node_map.get(provider_orig_index)

            if provider_dense_index is not None:
                provider_embedding = final_embeddings[provider_dense_index]
                # Calculate link score (similarity)
                link_score = torch.dot(seeker_embedding, provider_embedding).item()
                scores[provider_row['Full Name']] = link_score

        # C. Generate and Display Recommendations
        if scores:
            top_recommendations = sorted(scores.items(), key=lambda item: item[1], reverse=True)[:5]

            print(f"\n--- Top 5 Job Provider Recommendations for {seeker_name} ---")
            print("Recommendations are based on matching learned features (Interests, Skills, Centrality).")
            for rank, (name, score) in enumerate(top_recommendations):
                print(f"  {rank + 1}. {name} (Link Score: {score:.4f})")
        else:
            print("No Job Provider profiles found to recommend.")

# Execute the Recommendation System
run_recommendation_system()

