import pandas as pd
import networkx as nx
import numpy as np
import warnings
import os
import sys

# Scikit-learn imports (guaranteed to work)
from sklearn.preprocessing import StandardScaler
from sklearn.feature_extraction.text import TfidfVectorizer
from sklearn.decomposition import PCA
from sklearn.metrics.pairwise import cosine_similarity # <<< NEW CORE LOGIC

warnings.filterwarnings('ignore', category=UserWarning)

# --- HYPERPARAMETERS & FILE PATHS ---
FILE_NAME = 'Final Graph Nodes.xlsx'
# -----------------------------------------------------------------------

def load_data_and_prepare_features(file_name):
    """Loads data, regenerates centrality (for features), and prepares the feature matrix X."""
    print(f"Loading and processing data from {file_name}...")
    try:
        df = pd.read_excel(file_name)
    except Exception as e:
        print(f"Error loading file: {e}")
        return None, None

    # Data Cleaning
    df['Full Name'] = df['Full Name'].astype(str).str.strip()
    df['Connections'] = pd.to_numeric(df['Connections'], errors='coerce').fillna(0).astype(int)
    if 'Label' not in df.columns and 'Label(type of profile)' in df.columns:
        df.rename(columns={'Label(type of profile)': 'Label'}, inplace=True)
    if 'Interests' not in df.columns: df['Interests'] = ''

    # 1. Recalculate Graph Structure & Centrality (Required for X matrix integrity)
    # This step is needed to calculate the 'degree' and 'betweenness' features.
    G = nx.Graph()
    for i, row in df.iterrows():
        G.add_node(i, connections=row['Connections'], label=row['Label'])

    subset_node_indices = list(df.index)
    for i in range(len(subset_node_indices)):
        for j in range(i + 1, len(subset_node_indices)):
            if abs(df.loc[subset_node_indices[i], 'Connections'] - df.loc[subset_node_indices[j], 'Connections']) <= 5:
                G.add_edge(subset_node_indices[i], subset_node_indices[j])

    degree_cent = nx.degree_centrality(G)
    betweenness_cent = nx.betweenness_centrality(G)
    df['degree'] = df.index.map(degree_cent).fillna(0)
    df['betweenness'] = df.index.map(betweenness_cent).fillna(0)

    # 2. FEATURE ENGINEERING (Combined Text + Numerical)
    print("--- Feature Engineering: Combining all text and numerical features ---")
    text_cols = ['About', 'Workplace', 'Skills', 'Interests']
    numerical_cols = ['Connections', 'degree', 'betweenness']

    for col in text_cols: df[col] = df[col].astype(str).fillna('')
    df['combined_text'] = df[text_cols].agg(' '.join, axis=1)

    # TF-IDF -> PCA
    vectorizer = TfidfVectorizer(max_features=1000, stop_words='english')
    tfidf_matrix = vectorizer.fit_transform(df['combined_text']).toarray()
    pca = PCA(n_components=100, random_state=42)
    text_features_pca = pca.fit_transform(tfidf_matrix)

    # Scaling
    numerical_features = df[numerical_cols].values.astype(np.float32)
    scaler = StandardScaler()
    numerical_features_scaled = scaler.fit_transform(numerical_features)

    # Combine ALL features (Total 3 + 100 = 103 features)
    X_rich_features = np.hstack([numerical_features_scaled, text_features_pca])

    # Return the full DataFrame and the final feature matrix
    return df, X_rich_features

# -----------------------------------------------------------------------
# --- MAIN INFERENCE SCRIPT (Cosine Similarity) ---
# -----------------------------------------------------------------------

def run_recommendation_system():
    df, X_features = load_data_and_prepare_features(FILE_NAME)

    if df is None: return

    # 1. Identify Seeker and Provider Feature Vectors
    job_seekers_df = df[df['Label'] == 'Job Seeker'].copy()
    job_providers_df = df[df['Label'] == 'Job Provider'].copy()

    # Get feature indices
    seeker_indices = job_seekers_df.index
    provider_indices = job_providers_df.index

    # Extract feature matrices for seekers and providers
    X_seekers = X_features[df.index.get_indexer(seeker_indices)]
    X_providers = X_features[df.index.get_indexer(provider_indices)]

    print("\n--- FEATURE-BASED COSINE SIMILARITY RECOMMENDER READY ---")

    while True:
        seeker_name = input("\nEnter the FULL NAME of the Job Seeker (or type 'quit'): ").strip()
        if seeker_name.lower() == 'quit':
            break

        # A. Find the seeker's feature vector
        try:
            seeker_df_row = job_seekers_df[job_seekers_df['Full Name'] == seeker_name]
            if seeker_df_row.empty:
                print(f"Error: Job Seeker profile '{seeker_name}' not found.")
                continue

            seeker_orig_index = seeker_df_row.index[0]
            seeker_feature_index = df.index.get_loc(seeker_orig_index)

            # The vector for the seeker
            seeker_vector = X_features[seeker_feature_index].reshape(1, -1)

        except Exception:
            print("Error processing input. Please check the exact name.")
            continue

        # B. Calculate similarity (Cosine Similarity)
        # This calculates similarity between the seeker's vector and ALL provider vectors
        similarity_scores = cosine_similarity(seeker_vector, X_providers)[0]

        # C. Map scores back to provider names
        scores = {}
        for i, provider_orig_index in enumerate(provider_indices):
            provider_name = df.loc[provider_orig_index, 'Full Name']
            scores[provider_name] = similarity_scores[i]

        # D. Generate and Display Recommendations
        top_recommendations = sorted(scores.items(), key=lambda item: item[1], reverse=True)[:5]

        print(f"\n--- Top 5 Job Provider Recommendations for {seeker_name} ---")
        print("Recommendations are based on Cosine Similarity of 103 Rich Features.")
        for rank, (name, score) in enumerate(top_recommendations):
            print(f"  {rank + 1}. {name} (Similarity Score: {score:.4f})")

# Execute the Recommendation System
run_recommendation_system()

#ADDING PROMXIMITY OF THAT USER FEATURE
import pandas as pd
import networkx as nx
import numpy as np
import warnings
import os
import sys

# Scikit-learn imports
from sklearn.preprocessing import StandardScaler
from sklearn.feature_extraction.text import TfidfVectorizer
from sklearn.decomposition import PCA
from sklearn.metrics.pairwise import cosine_similarity

warnings.filterwarnings('ignore', category=UserWarning)

# --- HYPERPARAMETERS & FILE PATHS ---
FILE_NAME = 'Final Graph Nodes.xlsx'
# Weights for combined score (Feature Match is prioritized)
WEIGHT_FEATURE = 0.7
WEIGHT_PROXIMITY = 0.3
# -----------------------------------------------------------------------

def load_data_and_prepare_features(file_name):
    """Loads data and regenerates the graph, centrality, and feature matrix X."""
    print(f"Loading and processing data from {file_name}...")
    try:
        df = pd.read_excel(file_name)
    except Exception as e:
        print(f"Error loading file: {e}")
        return None, None

    # Data Cleaning and Preparation
    df['Full Name'] = df['Full Name'].astype(str).str.strip()
    df['Connections'] = pd.to_numeric(df['Connections'], errors='coerce').fillna(0).astype(int)
    if 'Label' not in df.columns and 'Label(type of profile)' in df.columns:
        df.rename(columns={'Label(type of profile)': 'Label'}, inplace=True)
    if 'Interests' not in df.columns: df['Interests'] = ''
    df['Location'] = df['Location'].astype(str).str.lower().fillna('') # Clean location for matching

    # 1. Recalculate Graph Structure & Centrality (Required for X matrix integrity)
    G = nx.Graph()
    for i, row in df.iterrows():
        G.add_node(i, connections=row['Connections'], label=row['Label'])
    subset_node_indices = list(df.index)
    for i in range(len(subset_node_indices)):
        for j in range(i + 1, len(subset_node_indices)):
            if abs(df.loc[subset_node_indices[i], 'Connections'] - df.loc[subset_node_indices[j], 'Connections']) <= 5:
                G.add_edge(subset_node_indices[i], subset_node_indices[j])

    degree_cent = nx.degree_centrality(G)
    betweenness_cent = nx.betweenness_centrality(G)
    df['degree'] = df.index.map(degree_cent).fillna(0)
    df['betweenness'] = df.index.map(betweenness_cent).fillna(0)

    # 2. FEATURE ENGINEERING (X matrix creation)
    text_cols = ['About', 'Workplace', 'Skills', 'Interests']
    numerical_cols = ['Connections', 'degree', 'betweenness']

    for col in text_cols: df[col] = df[col].astype(str).fillna('')
    df['combined_text'] = df[text_cols].agg(' '.join, axis=1)

    # TF-IDF -> PCA
    vectorizer = TfidfVectorizer(max_features=1000, stop_words='english')
    tfidf_matrix = vectorizer.fit_transform(df['combined_text']).toarray()
    pca = PCA(n_components=100, random_state=42)
    text_features_pca = pca.fit_transform(tfidf_matrix)

    # Scaling
    numerical_features = df[numerical_cols].values.astype(np.float32)
    scaler = StandardScaler()
    numerical_features_scaled = scaler.fit_transform(numerical_features)

    # Combine ALL features
    X_rich_features = np.hstack([numerical_features_scaled, text_features_pca])

    # Return the full DataFrame (with Location) and the final feature matrix
    return df, X_rich_features

# -----------------------------------------------------------------------
# --- MAIN INFERENCE SCRIPT (Cosine Similarity + Proximity) ---
# -----------------------------------------------------------------------

def run_recommendation_system():
    df, X_features = load_data_and_prepare_features(FILE_NAME)

    if df is None: return

    # 1. Prepare Feature Vectors
    job_seekers_df = df[df['Label'] == 'Job Seeker'].copy()
    job_providers_df = df[df['Label'] == 'Job Provider'].copy()

    # Get feature indices for easy slicing
    seeker_indices = job_seekers_df.index
    provider_indices = job_providers_df.index

    # Extract feature matrices for providers
    X_providers = X_features[df.index.get_indexer(provider_indices)]

    print("\n--- FEATURE + PROXIMITY RECOMMENDATION SYSTEM READY ---")

    while True:
        seeker_name = input("\nEnter the FULL NAME of the Job Seeker (or type 'quit'): ").strip()
        if seeker_name.lower() == 'quit':
            break

        seeker_location = input("Enter your desired location (e.g., 'New York City' or 'New Delhi'): ").strip().lower()
        if not seeker_location:
            print("Location cannot be empty.")
            continue

        # A. Find the seeker's feature vector
        try:
            seeker_df_row = job_seekers_df[job_seekers_df['Full Name'] == seeker_name]
            if seeker_df_row.empty or seeker_df_row['Full Name'].iloc[0] != seeker_name:
                print(f"Error: Job Seeker profile '{seeker_name}' not found.")
                continue

            seeker_orig_index = seeker_df_row.index[0]
            seeker_feature_index = df.index.get_loc(seeker_orig_index)
            seeker_vector = X_features[seeker_feature_index].reshape(1, -1)

        except Exception as e:
            print(f"Error processing input: {e}. Please check the exact name.")
            continue

        # B. Calculate similarity (Feature Score)
        # Calculates similarity between the seeker's vector and ALL provider vectors
        feature_scores = cosine_similarity(seeker_vector, X_providers)[0]

        scores = {}
        for i, provider_orig_index in enumerate(provider_indices):
            provider_name = df.loc[provider_orig_index, 'Full Name']

            # 1. Feature Match Score
            score_feature = feature_scores[i]

            # 2. Proximity Score (Binary String Match)
            provider_location = df.loc[provider_orig_index, 'Location']
            score_proximity = 1.0 if seeker_location in provider_location else 0.0

            # 3. Combined Weighted Score
            score_combined = (WEIGHT_FEATURE * score_feature) + (WEIGHT_PROXIMITY * score_proximity)

            scores[provider_name] = (score_combined, score_feature, score_proximity)

        # C. Generate and Display Recommendations
        # Rank based on the combined score (scores[name][0])
        top_recommendations = sorted(scores.items(), key=lambda item: item[1][0], reverse=True)[:7] # Top 7 results

        print(f"\n--- Top 7 Job Provider Recommendations for {seeker_name} (near {seeker_location.upper()}) ---")
        print(f"Ranking: (70% Feature Match + 30% Proximity)")
        print("{:<3} {:<30} {:>10} {:>10} {:>10}".format("No.", "Provider Name", "Combined", "Feature", "Proximity"))
        print("-" * 64)

        for rank, (name, (combined, feature, proximity)) in enumerate(top_recommendations):
            print("{:<3} {:<30} {:>10.4f} {:>10.4f} {:>10.1f}".format(
                rank + 1, name, combined, feature, proximity
            ))

# Execute the Recommendation System
run_recommendation_system()

# MOST COMPLEX PART OF RECCOMENDATION SYSYTEM THAT IS COLD START (FEEDING SOMETHING WHICH IS NOT EVEN IN DATASET )
import pandas as pd
import networkx as nx
import numpy as np
import warnings
import os
import sys

# Scikit-learn imports (guaranteed to work)
from sklearn.preprocessing import StandardScaler
from sklearn.feature_extraction.text import TfidfVectorizer
from sklearn.decomposition import PCA
from sklearn.metrics.pairwise import cosine_similarity

warnings.filterwarnings('ignore', category=UserWarning)

# --- HYPERPARAMETERS & FILE PATHS ---
FILE_NAME = 'Final Graph Nodes.xlsx'
WEIGHT_FEATURE = 0.7
WEIGHT_PROXIMITY = 0.3
# -----------------------------------------------------------------------

def load_data_and_fit_transformers(file_name):
    """
    Loads data, calculates centrality features, fits and returns the feature transformers,
    and returns the final feature matrix X.
    """
    print(f"Loading and processing data from {file_name}...")
    try:
        df = pd.read_excel(file_name)
    except Exception as e:
        print(f"Error loading file: {e}")
        return None, None, None

    # Data Cleaning and Feature Generation (Must be IDENTICAL to previous runs)
    df['Full Name'] = df['Full Name'].astype(str).str.strip()
    df['Connections'] = pd.to_numeric(df['Connections'], errors='coerce').fillna(0).astype(int)
    if 'Label' not in df.columns and 'Label(type of profile)' in df.columns:
        df.rename(columns={'Label(type of profile)': 'Label'}, inplace=True)
    if 'Interests' not in df.columns: df['Interests'] = ''
    df['Location_CLEAN'] = df['Location'].astype(str).str.lower().str.strip().fillna('')
    df['Location'] = df['Location'].astype(str).fillna('')

    # Recalculate Centrality Features (required for numerical X matrix)
    G = nx.Graph()
    for i, row in df.iterrows():
        G.add_node(i, connections=row['Connections'])
    subset_node_indices = list(df.index)
    for i in range(len(subset_node_indices)):
        for j in range(i + 1, len(subset_node_indices)):
            if abs(df.loc[subset_node_indices[i], 'Connections'] - df.loc[subset_node_indices[j], 'Connections']) <= 5:
                G.add_edge(subset_node_indices[i], subset_node_indices[j])

    degree_cent = nx.degree_centrality(G)
    betweenness_cent = nx.betweenness_centrality(G)
    df['degree'] = df.index.map(degree_cent).fillna(0)
    df['betweenness'] = df.index.map(betweenness_cent).fillna(0)

    # 2. FEATURE FITTING & TRANSFORMATION
    text_cols = ['About', 'Workplace', 'Skills', 'Interests']
    numerical_cols = ['Connections', 'degree', 'betweenness']

    for col in text_cols: df[col] = df[col].astype(str).fillna('')
    df['combined_text'] = df[text_cols].agg(' '.join, axis=1)

    # A. TF-IDF & PCA (Fit on existing data)
    vectorizer = TfidfVectorizer(max_features=1000, stop_words='english')
    tfidf_matrix = vectorizer.fit_transform(df['combined_text']).toarray()

    pca = PCA(n_components=100, random_state=42)
    text_features_pca = pca.fit_transform(tfidf_matrix)

    # B. StandardScaler (Fit on existing data)
    numerical_features = df[numerical_cols].values.astype(np.float32)
    scaler = StandardScaler()
    numerical_features_scaled = scaler.fit_transform(numerical_features)

    # Combine ALL features (Total 3 + 100 = 103 features)
    X_rich_features = np.hstack([numerical_features_scaled, text_features_pca])

    # Store numerical means/zeros for imputation during cold-start
    numerical_imputer = {
        'Connections_mean': df['Connections'].mean(),
        'scaler': scaler
    }

    print("Feature preparation complete. Transformers fitted.")
    # Return fitted transformers and the provider feature matrix
    return df, X_rich_features, vectorizer, pca, numerical_imputer

def create_synthetic_feature_vector(skills_input, location_input, vectorizer, pca, numerical_imputer):
    """Creates a 103-dimensional feature vector for a new, cold-start user."""

    # 1. SYNTHETIC NUMERICAL FEATURES
    # Impute Connections with the mean; Degree/Betweenness are 0 (isolated)
    numerical_data = np.array([[
        numerical_imputer['Connections_mean'],
        0.0, # Degree (Isolated)
        0.0  # Betweenness (Isolated)
    ]]).astype(np.float32)

    # Apply the fitted scaler
    numerical_features_scaled = numerical_imputer['scaler'].transform(numerical_data)

    # 2. TEXT FEATURES (Skills/Interests)
    # The input text must contain all text fields, but we only have skills/interests
    # Assume the user's input covers all text aspects.
    text_input = [f"{skills_input} {skills_input} {skills_input}"] # Repeat to simulate richness

    # Apply fitted TF-IDF and PCA
    tfidf_vector = vectorizer.transform(text_input).toarray()
    text_features_pca = pca.transform(tfidf_vector)

    # 3. Combine and return the 103-dim vector
    return np.hstack([numerical_features_scaled, text_features_pca])


# -----------------------------------------------------------------------
# --- MAIN INFERENCE SCRIPT (Cosine Similarity + Proximity) ---
# -----------------------------------------------------------------------

def run_recommendation_system():
    # Load data and fit all transformers
    df, X_features, vectorizer, pca, numerical_imputer = load_data_and_fit_transformers(FILE_NAME)

    if df is None: return

    # Prepare Provider Feature Vectors
    job_providers_df = df[df['Label'] == 'Job Provider'].copy()
    provider_indices = job_providers_df.index
    # Feature matrix for ONLY providers
    X_providers = X_features[df.index.get_indexer(provider_indices)]

    print("\n--- COLD-START FEATURE RECOMMENDER READY ---")

    while True:
        seeker_name = input("\nEnter your Name (New User/Job Seeker, or 'quit'): ").strip()
        if seeker_name.lower() == 'quit': break

        seeker_skills = input("Enter your SKILLS/INTERESTS (comma separated): ").strip()
        seeker_location_input = input("Enter your desired LOCATION: ").strip().lower()

        if not seeker_skills or not seeker_location_input:
            print("Skills/Interests and Location are required. Please try again.")
            continue

        # A. Create the synthetic feature vector for the new user
        seeker_vector = create_synthetic_feature_vector(
            seeker_skills, seeker_location_input, vectorizer, pca, numerical_imputer
        )

        # B. Calculate similarity (Feature Score)
        # Calculates similarity between the synthetic seeker's vector and ALL provider vectors
        feature_scores = cosine_similarity(seeker_vector, X_providers)[0]

        scores = {}
        for i, provider_orig_index in enumerate(provider_indices):

            # 1. Feature Match Score
            score_feature = feature_scores[i]

            # 2. Proximity Score (Binary String Match)
            provider_location_clean = df.loc[provider_orig_index, 'Location_CLEAN']
            # CRITICAL: If the user's input location is found in the provider's location string, give a bonus.
            score_proximity = 1.0 if seeker_location_input in provider_location_clean else 0.0

            # 3. Combined Weighted Score
            score_combined = (WEIGHT_FEATURE * score_feature) + (WEIGHT_PROXIMITY * score_proximity)

            scores[df.loc[provider_orig_index, 'Full Name']] = (score_combined, score_feature, score_proximity)

        # C. Generate and Display Recommendations
        top_recommendations = sorted(scores.items(), key=lambda item: item[1][0], reverse=True)[:7]

        print(f"\n--- Top 7 Job Provider Recommendations for {seeker_name} (near {seeker_location_input.upper()}) ---")
        print(f"Ranking: ({WEIGHT_FEATURE*100:.0f}% Skill Match + {WEIGHT_PROXIMITY*100:.0f}% Proximity Bonus)")
        print("{:<3} {:<30} {:>10} {:>10} {:>10} {:>15}".format("No.", "Provider Name", "Combined", "Feature", "Proximity", "Provider Location"))
        print("-" * 75)

        for rank, (name, (combined, feature, proximity)) in enumerate(top_recommendations):
            provider_location_original = df[df['Full Name'] == name]['Location'].iloc[0]

            print("{:<3} {:<30} {:>10.4f} {:>10.4f} {:>10.1f} {:>15}".format(
                rank + 1, name, combined, feature, proximity, provider_location_original
            ))

# Execute the Recommendation System
run_recommendation_system()

#Both WARM AND COLD START

import pandas as pd
import networkx as nx
import numpy as np
import warnings
import os
import sys

# Scikit-learn imports (guaranteed to work)
from sklearn.preprocessing import StandardScaler
from sklearn.feature_extraction.text import TfidfVectorizer
from sklearn.decomposition import PCA
from sklearn.metrics.pairwise import cosine_similarity

warnings.filterwarnings('ignore', category=UserWarning)

# --- HYPERPARAMETERS & FILE PATHS ---
FILE_NAME = 'Final Graph Nodes.xlsx'
WEIGHT_FEATURE = 0.7
WEIGHT_PROXIMITY = 0.3
# -----------------------------------------------------------------------

def load_data_and_fit_transformers(file_name):
    """
    Loads data, calculates centrality features, fits and returns the feature transformers,
    and returns the final feature matrix X.
    """
    print(f"Loading and processing data from {file_name}...")
    try:
        df = pd.read_excel(file_name)
    except Exception as e:
        print(f"Error loading file: {e}")
        return None, None, None, None, None

    # Data Cleaning and Feature Generation Setup
    df['Full Name'] = df['Full Name'].astype(str).str.strip()
    df['Connections'] = pd.to_numeric(df['Connections'], errors='coerce').fillna(0).astype(int)
    if 'Label' not in df.columns and 'Label(type of profile)' in df.columns:
        df.rename(columns={'Label(type of profile)': 'Label'}, inplace=True)
    if 'Interests' not in df.columns: df['Interests'] = ''
    df['Location_CLEAN'] = df['Location'].astype(str).str.lower().str.strip().fillna('')
    df['Location'] = df['Location'].astype(str).fillna('')

    # Recalculate Centrality Features (required for numerical X matrix)
    G = nx.Graph()
    for i, row in df.iterrows(): G.add_node(i, connections=row['Connections'])
    subset_node_indices = list(df.index)
    for i in range(len(subset_node_indices)):
        for j in range(i + 1, len(subset_node_indices)):
            if abs(df.loc[subset_node_indices[i], 'Connections'] - df.loc[subset_node_indices[j], 'Connections']) <= 5:
                G.add_edge(subset_node_indices[i], subset_node_indices[j])

    degree_cent = nx.degree_centrality(G)
    betweenness_cent = nx.betweenness_centrality(G)
    df['degree'] = df.index.map(degree_cent).fillna(0)
    df['betweenness'] = df.index.map(betweenness_cent).fillna(0)

    # 2. FEATURE FITTING & TRANSFORMATION
    text_cols = ['About', 'Workplace', 'Skills', 'Interests']
    numerical_cols = ['Connections', 'degree', 'betweenness']

    for col in text_cols: df[col] = df[col].astype(str).fillna('')
    df['combined_text'] = df[text_cols].agg(' '.join, axis=1)

    # A. TF-IDF & PCA (Fit on existing data)
    vectorizer = TfidfVectorizer(max_features=1000, stop_words='english')
    tfidf_matrix = vectorizer.fit_transform(df['combined_text']).toarray()

    pca = PCA(n_components=100, random_state=42)
    text_features_pca = pca.fit_transform(tfidf_matrix)

    # B. StandardScaler (Fit on existing data)
    numerical_features = df[numerical_cols].values.astype(np.float32)
    scaler = StandardScaler()
    numerical_features_scaled = scaler.fit_transform(numerical_features)

    # Combine ALL features (Total 3 + 100 = 103 features)
    X_rich_features = np.hstack([numerical_features_scaled, text_features_pca])

    numerical_imputer = {
        'Connections_mean': df['Connections'].mean(),
        'scaler': scaler
    }

    print("Feature preparation complete. Transformers fitted.")
    # Return fitted transformers and the provider feature matrix
    return df, X_rich_features, vectorizer, pca, numerical_imputer

def create_synthetic_feature_vector(skills_input, vectorizer, pca, numerical_imputer):
    """Creates a 103-dimensional feature vector for a new, cold-start user."""

    # 1. SYNTHETIC NUMERICAL FEATURES (Impute Connection mean, set Centrality to 0)
    numerical_data = np.array([[
        numerical_imputer['Connections_mean'],
        0.0, # Degree (Isolated)
        0.0  # Betweenness (Isolated)
    ]]).astype(np.float32)

    # Apply the fitted scaler
    numerical_features_scaled = numerical_imputer['scaler'].transform(numerical_data)

    # 2. TEXT FEATURES (Skills/Interests)
    text_input = [f"{skills_input} {skills_input} {skills_input}"]

    # Apply fitted TF-IDF and PCA
    tfidf_vector = vectorizer.transform(text_input).toarray()
    text_features_pca = pca.transform(tfidf_vector)

    # 3. Combine and return the 103-dim vector
    return np.hstack([numerical_features_scaled, text_features_pca])



# --- MAIN INFERENCE SCRIPT (Cosine Similarity + Proximity) ---


def run_recommendation_system():
    # Load data and fit all transformers
    df, X_features, vectorizer, pca, numerical_imputer = load_data_and_fit_transformers(FILE_NAME)

    if df is None: return

    # Prepare Provider Feature Vectors
    job_providers_df = df[df['Label'] == 'Job Provider'].copy()
    provider_indices = job_providers_df.index
    X_providers = X_features[df.index.get_indexer(provider_indices)]

    print("\n--- INTEGRATED WARM/COLD START RECOMMENDER READY ---")

    while True:
        mode = input("\nSelect Mode: (1) Existing User or (2) New User (or 'quit'): ").strip()
        if mode.lower() == 'quit': break

        seeker_vector = None
        seeker_location_input = None

        if mode == '1': # Existing User (Warm Start)
            # --- WARM START LOGIC ---
            seeker_name = input("Enter your FULL NAME (from the dataset): ").strip()
            seeker_df_row = df[df['Full Name'] == seeker_name]

            if seeker_df_row.empty or seeker_df_row['Label'].iloc[0] != 'Job Seeker':
                print(f"Error: Profile '{seeker_name}' not found or is not a Job Seeker.")
                continue

            seeker_orig_index = seeker_df_row.index[0]
            seeker_feature_index = df.index.get_loc(seeker_orig_index)
            seeker_vector = X_features[seeker_feature_index].reshape(1, -1)

            # Use the user's actual location from the DataFrame
            seeker_location_input = df.loc[seeker_orig_index, 'Location'].strip().lower()
            print(f"-> Found user's location: {seeker_location_input.upper()}")

        elif mode == '2': # New User (Cold Start)
            # --- COLD START LOGIC ---
            seeker_name = input("Enter your NAME (New User): ").strip()
            seeker_skills = input("Enter your SKILLS/INTERESTS (comma separated): ").strip()
            seeker_location_input = input("Enter your DESIRED LOCATION: ").strip().lower()

            if not seeker_skills or not seeker_location_input:
                print("Skills/Interests and Location are required. Please try again.")
                continue

            seeker_vector = create_synthetic_feature_vector(
                seeker_skills, vectorizer, pca, numerical_imputer
            )

        else:
            print("Invalid mode selected. Please enter '1' or '2'.")
            continue

        if seeker_vector is None: continue

        # B. Calculate similarity (Feature Score)
        feature_scores = cosine_similarity(seeker_vector, X_providers)[0]

        scores = {}
        for i, provider_orig_index in enumerate(provider_indices):

            # 1. Feature Match Score
            score_feature = feature_scores[i]

            # 2. Proximity Score (Binary String Match)
            provider_location_clean = df.loc[provider_orig_index, 'Location_CLEAN']
            # Check if the seeker's input location is found in the provider's location string.
            score_proximity = 1.0 if seeker_location_input in provider_location_clean else 0.0

            # 3. Combined Weighted Score
            score_combined = (WEIGHT_FEATURE * score_feature) + (WEIGHT_PROXIMITY * score_proximity)

            scores[df.loc[provider_orig_index, 'Full Name']] = (score_combined, score_feature, score_proximity)

        # C. Generate and Display Recommendations
        top_recommendations = sorted(scores.items(), key=lambda item: item[1][0], reverse=True)[:7]

        print(f"\n--- Top 7 Job Provider Recommendations for {seeker_name} ---")
        print(f"Location Used for Proximity: {seeker_location_input.upper()}")
        print(f"Ranking: ({WEIGHT_FEATURE*100:.0f}% Skill Match + {WEIGHT_PROXIMITY*100:.0f}% Proximity Bonus)")
        print("{:<3} {:<30} {:>10} {:>10} {:>10} {:>15}".format("No.", "Provider Name", "Combined", "Feature", "Proximity", "Provider Location"))
        print("-" * 75)

        for rank, (name, (combined, feature, proximity)) in enumerate(top_recommendations):
            provider_location_original = df[df['Full Name'] == name]['Location'].iloc[0]

            print("{:<3} {:<30} {:>10.4f} {:>10.4f} {:>10.1f} {:>15}".format(
                rank + 1, name, combined, feature, proximity, provider_location_original
            ))

# Execute the Recommendation System
run_recommendation_system()

import pandas as pd
import networkx as nx
import numpy as np
import warnings
import os
import sys

# Scikit-learn imports (guaranteed to work)
from sklearn.preprocessing import StandardScaler
from sklearn.feature_extraction.text import TfidfVectorizer
from sklearn.decomposition import PCA
from sklearn.metrics.pairwise import cosine_similarity

warnings.filterwarnings('ignore', category=UserWarning)

# --- HYPERPARAMETERS & FILE PATHS ---
FILE_NAME = 'Final Graph Nodes.xlsx'
WEIGHT_FEATURE = 0.7
WEIGHT_PROXIMITY = 0.3

# --- OPTIMIZATION: DAMPEN STRUCTURAL FEATURES ---
# Structural features (Connections, Degree, Betweenness) contribute only 10% of their scaled variance.
STRUCTURAL_WEIGHT = 0.1
# -----------------------------------------------------------------------

def load_data_and_fit_transformers(file_name):
    """
    Loads data, calculates centrality features, fits and returns the feature transformers,
    and returns the final feature matrix X.
    """
    print(f"Loading and processing data from {file_name}...")
    try:
        df = pd.read_excel(file_name)
    except Exception as e:
        print(f"Error loading file: {e}")
        return None, None, None, None, None

    # Data Cleaning and Feature Generation Setup
    df['Full Name'] = df['Full Name'].astype(str).str.strip()
    df['Connections'] = pd.to_numeric(df['Connections'], errors='coerce').fillna(0).astype(int)
    if 'Label' not in df.columns and 'Label(type of profile)' in df.columns:
        df.rename(columns={'Label(type of profile)': 'Label'}, inplace=True)
    if 'Interests' not in df.columns: df['Interests'] = ''
    df['Location_CLEAN'] = df['Location'].astype(str).str.lower().str.strip().fillna('')
    df['Location'] = df['Location'].astype(str).fillna('')

    # Recalculate Centrality Features (required for numerical X matrix)
    G = nx.Graph()
    for i, row in df.iterrows(): G.add_node(i, connections=row['Connections'])
    subset_node_indices = list(df.index)
    for i in range(len(subset_node_indices)):
        for j in range(i + 1, len(subset_node_indices)):
            if abs(df.loc[subset_node_indices[i], 'Connections'] - df.loc[subset_node_indices[j], 'Connections']) <= 5:
                G.add_edge(subset_node_indices[i], subset_node_indices[j])

    degree_cent = nx.degree_centrality(G)
    betweenness_cent = nx.betweenness_centrality(G)
    df['degree'] = df.index.map(degree_cent).fillna(0)
    df['betweenness'] = df.index.map(betweenness_cent).fillna(0)

    # 2. FEATURE FITTING & TRANSFORMATION
    text_cols = ['About', 'Workplace', 'Skills', 'Interests']
    numerical_cols = ['Connections', 'degree', 'betweenness']

    for col in text_cols: df[col] = df[col].astype(str).fillna('')
    df['combined_text'] = df[text_cols].agg(' '.join, axis=1)

    # A. TF-IDF & PCA (Fit on existing data)
    vectorizer = TfidfVectorizer(max_features=1000, stop_words='english')
    tfidf_matrix = vectorizer.fit_transform(df['combined_text']).toarray()

    pca = PCA(n_components=100, random_state=42)
    text_features_pca = pca.fit_transform(tfidf_matrix)

    # B. StandardScaler (Fit on existing data)
    numerical_features = df[numerical_cols].values.astype(np.float32)
    scaler = StandardScaler()
    numerical_features_scaled = scaler.fit_transform(numerical_features)

    # C. COMBINE WITH DAMPENING
    # Dampen the scaled numerical features before combining with text
    X_rich_features = np.hstack([numerical_features_scaled * STRUCTURAL_WEIGHT, text_features_pca])

    numerical_imputer = {
        'Connections_mean': df['Connections'].mean(),
        'scaler': scaler
    }

    print("Feature preparation complete. Transformers fitted.")
    return df, X_rich_features, vectorizer, pca, numerical_imputer

def create_synthetic_feature_vector(skills_input, vectorizer, pca, numerical_imputer):
    """Creates a 103-dimensional feature vector for a new, cold-start user."""

    # 1. SYNTHETIC NUMERICAL FEATURES
    numerical_data = np.array([[
        numerical_imputer['Connections_mean'],
        0.0,
        0.0
    ]]).astype(np.float32)

    numerical_features_scaled = numerical_imputer['scaler'].transform(numerical_data)

    # 2. TEXT FEATURES (Skills/Interests)
    text_input = [f"{skills_input} {skills_input} {skills_input}"]

    tfidf_vector = vectorizer.transform(text_input).toarray()
    text_features_pca = pca.transform(tfidf_vector)

    # 3. COMBINE WITH DAMPENING (must mirror the combination in load_data_and_fit_transformers)
    return np.hstack([numerical_features_scaled * STRUCTURAL_WEIGHT, text_features_pca])


# -----------------------------------------------------------------------
# --- MAIN INFERENCE SCRIPT (Cosine Similarity + Proximity) ---
# -----------------------------------------------------------------------

def run_recommendation_system():
    # Load data and fit all transformers
    df, X_features, vectorizer, pca, numerical_imputer = load_data_and_fit_transformers(FILE_NAME)

    if df is None: return

    # Prepare Provider Feature Vectors
    job_providers_df = df[df['Label'] == 'Job Provider'].copy()
    provider_indices = job_providers_df.index
    X_providers = X_features[df.index.get_indexer(provider_indices)]

    print("\n--- INTEGRATED WARM/COLD START RECOMMENDER READY ---")

    while True:
        mode = input("\nSelect Mode: (1) Existing User or (2) New User (or 'quit'): ").strip()
        if mode.lower() == 'quit': break

        seeker_vector = None
        seeker_location_input = None

        if mode == '1': # Existing User (Warm Start)
            # --- WARM START LOGIC ---
            seeker_name = input("Enter your FULL NAME (from the dataset): ").strip()
            seeker_df_row = df[df['Full Name'] == seeker_name]

            if seeker_df_row.empty or seeker_df_row['Label'].iloc[0] != 'Job Seeker':
                print(f"Error: Profile '{seeker_name}' not found or is not a Job Seeker.")
                continue

            seeker_orig_index = seeker_df_row.index[0]
            seeker_feature_index = df.index.get_loc(seeker_orig_index)
            seeker_vector = X_features[seeker_feature_index].reshape(1, -1)

            # Use the user's actual location from the DataFrame
            seeker_location_input = df.loc[seeker_orig_index, 'Location'].strip().lower()
            print(f"-> Found user's location: {seeker_location_input.upper()}")

        elif mode == '2': # New User (Cold Start)
            # --- COLD START LOGIC ---
            seeker_name = input("Enter your NAME (New User): ").strip()
            seeker_skills = input("Enter your SKILLS/INTERESTS (comma separated): ").strip()
            seeker_location_input = input("Enter your DESIRED LOCATION: ").strip().lower()

            if not seeker_skills or not seeker_location_input:
                print("Skills/Interests and Location are required. Please try again.")
                continue

            seeker_vector = create_synthetic_feature_vector(
                seeker_skills, vectorizer, pca, numerical_imputer
            )

        else:
            print("Invalid mode selected. Please enter '1' or '2'.")
            continue

        if seeker_vector is None: continue

        # B. Calculate similarity (Feature Score)
        feature_scores = cosine_similarity(seeker_vector, X_providers)[0]

        scores = {}
        for i, provider_orig_index in enumerate(provider_indices):

            # 1. Feature Match Score
            score_feature = feature_scores[i]

            # 2. Proximity Score (Binary String Match)
            provider_location_clean = df.loc[provider_orig_index, 'Location_CLEAN']
            score_proximity = 1.0 if seeker_location_input in provider_location_clean else 0.0

            # 3. Combined Weighted Score
            score_combined = (WEIGHT_FEATURE * score_feature) + (WEIGHT_PROXIMITY * score_proximity)

            scores[df.loc[provider_orig_index, 'Full Name']] = (score_combined, score_feature, score_proximity)

        # C. Generate and Display Recommendations
        top_recommendations = sorted(scores.items(), key=lambda item: item[1][0], reverse=True)[:7]

        print(f"\n--- Top 7 Job Provider Recommendations for {seeker_name} ---")
        print(f"Location Used for Proximity: {seeker_location_input.upper()}")
        print(f"Ranking: ({WEIGHT_FEATURE*100:.0f}% Skill Match + {WEIGHT_PROXIMITY*100:.0f}% Proximity Bonus)")
        print("{:<3} {:<30} {:>10} {:>10} {:>10} {:>15}".format("No.", "Provider Name", "Combined", "Feature", "Proximity", "Provider Location"))
        print("-" * 75)

        for rank, (name, (combined, feature, proximity)) in enumerate(top_recommendations):
            provider_location_original = df[df['Full Name'] == name]['Location'].iloc[0]

            print("{:<3} {:<30} {:>10.4f} {:>10.4f} {:>10.1f} {:>15}".format(
                rank + 1, name, combined, feature, proximity, provider_location_original
            ))

# Execute the Recommendation System
run_recommendation_system()

import pandas as pd
import networkx as nx
import numpy as np
import warnings
import os
import sys

# Scikit-learn imports (guaranteed to work)
from sklearn.preprocessing import StandardScaler
from sklearn.feature_extraction.text import TfidfVectorizer
from sklearn.decomposition import PCA
from sklearn.metrics.pairwise import cosine_similarity

warnings.filterwarnings('ignore', category=UserWarning)

# --- HYPERPARAMETERS & FILE PATHS ---
FILE_NAME = 'Final Graph Nodes.xlsx'
WEIGHT_FEATURE = 0.7
WEIGHT_PROXIMITY = 0.3
STRUCTURAL_WEIGHT = 0.1 # Dampen structural features by 90%
# -----------------------------------------------------------------------

def load_data_and_fit_transformers(file_name):
    """
    Loads data, calculates centrality features, fits and returns the feature transformers,
    and returns the final feature matrix X.
    """
    print(f"Loading and processing data from {file_name}...")
    try:
        df = pd.read_excel(file_name)
    except Exception as e:
        print(f"Error loading file: {e}")
        return None, None, None, None, None

    # Data Cleaning and Feature Generation Setup
    df['Full Name'] = df['Full Name'].astype(str).str.strip()
    df['Connections'] = pd.to_numeric(df['Connections'], errors='coerce').fillna(0).astype(int)
    if 'Label' not in df.columns and 'Label(type of profile)' in df.columns:
        df.rename(columns={'Label(type of profile)': 'Label'}, inplace=True)
    if 'Interests' not in df.columns: df['Interests'] = ''
    df['Location_CLEAN'] = df['Location'].astype(str).str.lower().str.strip().fillna('')
    df['Location'] = df['Location'].astype(str).fillna('')

    # Recalculate Centrality Features
    G = nx.Graph()
    for i, row in df.iterrows(): G.add_node(i, connections=row['Connections'])
    subset_node_indices = list(df.index)
    for i in range(len(subset_node_indices)):
        for j in range(i + 1, len(subset_node_indices)):
            if abs(df.loc[subset_node_indices[i], 'Connections'] - df.loc[subset_node_indices[j], 'Connections']) <= 5:
                G.add_edge(subset_node_indices[i], subset_node_indices[j])

    degree_cent = nx.degree_centrality(G)
    betweenness_cent = nx.betweenness_centrality(G)
    df['degree'] = df.index.map(degree_cent).fillna(0)
    df['betweenness'] = df.index.map(betweenness_cent).fillna(0)

    # 2. FEATURE FITTING & TRANSFORMATION
    text_cols = ['About', 'Workplace', 'Skills', 'Interests']
    numerical_cols = ['Connections', 'degree', 'betweenness']

    for col in text_cols: df[col] = df[col].astype(str).fillna('')
    df['combined_text'] = df[text_cols].agg(' '.join, axis=1)

    # A. TF-IDF & PCA (Fit on existing data)
    vectorizer = TfidfVectorizer(max_features=1000, stop_words='english')
    tfidf_matrix = vectorizer.fit_transform(df['combined_text']).toarray()

    pca = PCA(n_components=100, random_state=42)
    text_features_pca = pca.fit_transform(tfidf_matrix)

    # B. StandardScaler (Fit on existing data)
    numerical_features = df[numerical_cols].values.astype(np.float32)
    scaler = StandardScaler()
    numerical_features_scaled = scaler.fit_transform(numerical_features)

    # C. COMBINE WITH DAMPENING
    # Dampen the scaled numerical features before combining with text
    X_rich_features = np.hstack([numerical_features_scaled * STRUCTURAL_WEIGHT, text_features_pca])

    numerical_imputer = {
        'Connections_mean': df['Connections'].mean(),
        'scaler': scaler
    }

    print("Feature preparation complete. Transformers fitted.")
    return df, X_rich_features, vectorizer, pca, numerical_imputer

def create_synthetic_feature_vector(skills_input, vectorizer, pca, numerical_imputer):
    """Creates a 103-dimensional feature vector for a new, cold-start user."""

    # 1. SYNTHETIC NUMERICAL FEATURES
    numerical_data = np.array([[
        numerical_imputer['Connections_mean'],
        0.0,
        0.0
    ]]).astype(np.float32)

    numerical_features_scaled = numerical_imputer['scaler'].transform(numerical_data)

    # 2. TEXT FEATURES (Skills/Interests)
    text_input = [f"{skills_input} {skills_input} {skills_input}"]

    tfidf_vector = vectorizer.transform(text_input).toarray()
    text_features_pca = pca.transform(tfidf_vector)

    # 3. COMBINE WITH DAMPENING
    return np.hstack([numerical_features_scaled * STRUCTURAL_WEIGHT, text_features_pca])


# -----------------------------------------------------------------------
# --- MAIN INFERENCE SCRIPT (Cosine Similarity + Proximity) ---
# -----------------------------------------------------------------------

def run_recommendation_system():
    # Load data and fit all transformers
    df, X_features, vectorizer, pca, numerical_imputer = load_data_and_fit_transformers(FILE_NAME)

    if df is None: return

    job_providers_df = df[df['Label'] == 'Job Provider'].copy()
    provider_indices = job_providers_df.index
    X_providers = X_features[df.index.get_indexer(provider_indices)]

    print("\n--- INTEGRATED WARM/COLD START RECOMMENDER READY ---")

    while True:
        mode = input("\nSelect Mode: (1) Existing User or (2) New User (or 'quit'): ").strip()
        if mode.lower() == 'quit': break

        seeker_vector = None
        seeker_location_input = None

        if mode == '1': # Existing User (Warm Start)
            # --- WARM START LOGIC ---
            seeker_name = input("Enter your FULL NAME (from the dataset): ").strip()
            seeker_df_row = df[df['Full Name'] == seeker_name]

            if seeker_df_row.empty or seeker_df_row['Label'].iloc[0] != 'Job Seeker':
                print(f"Error: Profile '{seeker_name}' not found or is not a Job Seeker.")
                continue

            seeker_orig_index = seeker_df_row.index[0]
            seeker_feature_index = df.index.get_loc(seeker_orig_index)
            seeker_vector = X_features[seeker_feature_index].reshape(1, -1)

            # Use the user's actual location from the DataFrame
            seeker_location_input = df.loc[seeker_orig_index, 'Location'].strip().lower()
            print(f"-> Found user's location: {seeker_location_input.upper()}")

        elif mode == '2': # New User (Cold Start)
            # --- COLD START LOGIC ---
            seeker_name = input("Enter your NAME (New User): ").strip()
            seeker_skills = input("Enter your SKILLS/INTERESTS (comma separated): ").strip()
            seeker_location_input = input("Enter your DESIRED LOCATION: ").strip().lower()

            if not seeker_skills or not seeker_location_input:
                print("Skills/Interests and Location are required. Please try again.")
                continue

            seeker_vector = create_synthetic_feature_vector(
                seeker_skills, vectorizer, pca, numerical_imputer
            )

        else:
            print("Invalid mode selected. Please enter '1' or '2'.")
            continue

        if seeker_vector is None: continue

        # B. Calculate similarity (Feature Score)
        feature_scores = cosine_similarity(seeker_vector, X_providers)[0]

        scores = {}
        for i, provider_orig_index in enumerate(provider_indices):

            # 1. Feature Match Score
            score_feature = feature_scores[i]

            # 2. Proximity Score (Binary String Match)
            provider_location_clean = df.loc[provider_orig_index, 'Location_CLEAN']
            score_proximity = 1.0 if seeker_location_input in provider_location_clean else 0.0

            # 3. Combined Weighted Score
            score_combined = (WEIGHT_FEATURE * score_feature) + (WEIGHT_PROXIMITY * score_proximity)

            scores[df.loc[provider_orig_index, 'Full Name']] = (score_combined, score_feature, score_proximity)

        # C. Generate and Display Recommendations
        top_recommendations = sorted(scores.items(), key=lambda item: item[1][0], reverse=True)[:7]

        print(f"\n--- Top 7 Job Provider Recommendations for {seeker_name} ---")
        print(f"Location Used for Proximity: {seeker_location_input.upper()}")
        print(f"Ranking: ({WEIGHT_FEATURE*100:.0f}% Skill Match + {WEIGHT_PROXIMITY*100:.0f}% Proximity Bonus)")
        print("{:<3} {:<30} {:>10} {:>10} {:>10} {:>15}".format("No.", "Provider Name", "Combined", "Feature", "Proximity", "Provider Location"))
        print("-" * 75)

        for rank, (name, (combined, feature, proximity)) in enumerate(top_recommendations):
            provider_location_original = df[df['Full Name'] == name]['Location'].iloc[0]

            print("{:<3} {:<30} {:>10.4f} {:>10.4f} {:>10.1f} {:>15}".format(
                rank + 1, name, combined, feature, proximity, provider_location_original
            ))

# Execute the Recommendation System
run_recommendation_system()

import pandas as pd
import networkx as nx
import numpy as np
import warnings
import os
import sys

# Scikit-learn imports (guaranteed to work)
from sklearn.preprocessing import StandardScaler
from sklearn.feature_extraction.text import TfidfVectorizer
from sklearn.decomposition import PCA
from sklearn.metrics.pairwise import cosine_similarity

warnings.filterwarnings('ignore', category=UserWarning)

# --- HYPERPARAMETERS & FILE PATHS ---
FILE_NAME = 'Final Graph Nodes.xlsx'
WEIGHT_FEATURE = 0.7
WEIGHT_PROXIMITY = 0.3
STRUCTURAL_WEIGHT = 0.1 # Dampen structural features by 90%
# -----------------------------------------------------------------------

def load_data_and_fit_transformers(file_name):
    """Loads data, calculates centrality features, fits and returns the feature transformers."""
    print(f"Loading and processing data from {file_name}...")
    try:
        df = pd.read_excel(file_name)
    except Exception as e:
        print(f"Error loading file: {e}")
        return None, None, None, None, None

    # Data Cleaning and Feature Generation Setup
    df['Full Name'] = df['Full Name'].astype(str).str.strip()
    df['Connections'] = pd.to_numeric(df['Connections'], errors='coerce').fillna(0).astype(int)
    if 'Label' not in df.columns and 'Label(type of profile)' in df.columns:
        df.rename(columns={'Label(type of profile)': 'Label'}, inplace=True)
    if 'Interests' not in df.columns: df['Interests'] = ''
    df['Location_CLEAN'] = df['Location'].astype(str).str.lower().str.strip().fillna('')
    df['Location'] = df['Location'].astype(str).fillna('')

    # Recalculate Centrality Features
    G = nx.Graph()
    for i, row in df.iterrows(): G.add_node(i, connections=row['Connections'])
    subset_node_indices = list(df.index)
    for i in range(len(subset_node_indices)):
        for j in range(i + 1, len(subset_node_indices)):
            # Graph building logic based on connection count proximity
            if abs(df.loc[subset_node_indices[i], 'Connections'] - df.loc[subset_node_indices[j], 'Connections']) <= 5:
                G.add_edge(subset_node_indices[i], subset_node_indices[j])

    degree_cent = nx.degree_centrality(G)
    betweenness_cent = nx.betweenness_centrality(G)
    df['degree'] = df.index.map(degree_cent).fillna(0)
    df['betweenness'] = df.index.map(betweenness_cent).fillna(0)

    # 2. FEATURE FITTING & TRANSFORMATION
    text_cols = ['About', 'Workplace', 'Skills', 'Interests']
    numerical_cols = ['Connections', 'degree', 'betweenness']

    for col in text_cols: df[col] = df[col].astype(str).fillna('')
    df['combined_text'] = df[text_cols].agg(' '.join, axis=1)

    # A. TF-IDF & PCA (Fit on existing data)
    vectorizer = TfidfVectorizer(max_features=1000, stop_words='english')
    tfidf_matrix = vectorizer.fit_transform(df['combined_text']).toarray()
    pca = PCA(n_components=100, random_state=42)
    text_features_pca = pca.fit_transform(tfidf_matrix)

    # B. StandardScaler (Fit on existing data)
    numerical_features = df[numerical_cols].values.astype(np.float32)
    scaler = StandardScaler()
    numerical_features_scaled = scaler.fit_transform(numerical_features)

    # C. COMBINE WITH DAMPENING
    X_rich_features = np.hstack([numerical_features_scaled * STRUCTURAL_WEIGHT, text_features_pca])

    # numerical_imputer now holds the scaler, which is crucial for new data
    numerical_imputer = {
        'scaler': scaler
    }
    return df, X_rich_features, vectorizer, pca, numerical_imputer

def create_synthetic_feature_vector(skills_input, connections_input, vectorizer, pca, numerical_imputer):
    """
    Creates a 103-dimensional feature vector for a new, cold-start user.
    MODIFIED: Uses actual user connection count instead of the mean.
    """

    # 1. SYNTHETIC NUMERICAL FEATURES
    # We use the actual connections count, but zero out the graph features
    # since the new user is not yet fully integrated into the graph.
    numerical_data = np.array([[
        connections_input,  # <<--- YOUR SUGGESTION INCORPORATED HERE
        0.0,  # Centrality: degree (assumed 0 initially)
        0.0   # Centrality: betweenness (assumed 0 initially)
    ]]).astype(np.float32)

    # Use the pre-fitted scaler to transform the new data
    numerical_features_scaled = numerical_imputer['scaler'].transform(numerical_data)

    # 2. TEXT FEATURES (Skills/Interests)
    # Tripling the input to give it more weight in TF-IDF/PCA space (common cold-start trick)
    text_input = [f"{skills_input} {skills_input} {skills_input}"]

    tfidf_vector = vectorizer.transform(text_input).toarray()
    text_features_pca = pca.transform(tfidf_vector)

    # 3. COMBINE WITH DAMPENING
    return np.hstack([numerical_features_scaled * STRUCTURAL_WEIGHT, text_features_pca])


# -----------------------------------------------------------------------
# --- MAIN INFERENCE SCRIPT (Cosine Similarity + Proximity) ---
# -----------------------------------------------------------------------

def run_recommendation_system():
    df, X_features, vectorizer, pca, numerical_imputer = load_data_and_fit_transformers(FILE_NAME)

    if df is None: return

    job_providers_df = df[df['Label'] == 'Job Provider'].copy()
    provider_indices = job_providers_df.index
    X_providers = X_features[df.index.get_indexer(provider_indices)]

    print("\n--- INTEGRATED WARM/COLD START RECOMMENDER READY ---")

    while True:
        mode = input("\nSelect Mode: (1) Existing User or (2) New User (or 'quit'): ").strip()
        if mode.lower() == 'quit': break

        seeker_vector = None
        seeker_location_input = None

        if mode == '1': # Existing User (Warm Start)
            seeker_name = input("Enter your FULL NAME (from the dataset): ").strip()
            seeker_df_row = df[df['Full Name'] == seeker_name]

            if seeker_df_row.empty or seeker_df_row['Label'].iloc[0] != 'Job Seeker':
                print(f"Error: Profile '{seeker_name}' not found or is not a Job Seeker.")
                continue

            seeker_orig_index = seeker_df_row.index[0]
            seeker_feature_index = df.index.get_loc(seeker_orig_index)
            seeker_vector = X_features[seeker_feature_index].reshape(1, -1)

            seeker_location_input = df.loc[seeker_orig_index, 'Location'].strip().lower()
            print(f"-> Found user's location: {seeker_location_input.upper()}")

        elif mode == '2': # New User (Cold Start)
            seeker_name = input("Enter your NAME (New User): ").strip()
            seeker_skills = input("Enter your SKILLS/INTERESTS (comma separated): ").strip()
            # --- NEW INPUT FIELD FOR COLD START CONNECTION COUNT ---
            try:
                seeker_connections = int(input("Enter your NUMBER OF CONNECTIONS: ").strip())
            except ValueError:
                print("Invalid connection count. Please enter a number.")
                continue
            # ------------------------------------------------------
            seeker_location_input = input("Enter your DESIRED LOCATION: ").strip().lower()

            if not seeker_skills or not seeker_location_input:
                print("Skills/Interests and Location are required. Please try again.")
                continue

            # --- MODIFIED FUNCTION CALL ---
            seeker_vector = create_synthetic_feature_vector(
                seeker_skills, seeker_connections, vectorizer, pca, numerical_imputer
            )
            # ------------------------------

        else:
            print("Invalid mode selected. Please enter '1' or '2'.")
            continue

        if seeker_vector is None: continue

        # B. Calculate similarity (Feature Score)
        feature_scores = cosine_similarity(seeker_vector, X_providers)[0]

        scores = {}
        for i, provider_orig_index in enumerate(provider_indices):

            score_feature = feature_scores[i]
            provider_location_clean = df.loc[provider_orig_index, 'Location_CLEAN']
            score_proximity = 1.0 if seeker_location_input in provider_location_clean else 0.0

            score_combined = (WEIGHT_FEATURE * score_feature) + (WEIGHT_PROXIMITY * score_proximity)

            scores[df.loc[provider_orig_index, 'Full Name']] = (score_combined, score_feature, score_proximity)

        # C. Generate and Display Recommendations (Two-Pass Ranking)

        local_providers = {}
        non_local_providers = {}
        for name, (combined, feature, proximity) in scores.items():
            if proximity == 1.0:
                local_providers[name] = (combined, feature, proximity)
            else:
                non_local_providers[name] = (combined, feature, proximity)

        # 1. Rank local providers by skill match (feature score)
        sorted_local = sorted(local_providers.items(), key=lambda item: item[1][1], reverse=True)

        # 2. Rank non-local providers by combined score (to fill remaining slots)
        sorted_non_local = sorted(non_local_providers.items(), key=lambda item: item[1][0], reverse=True)

        # 3. Combine top results (Local matches get absolute priority)
        top_recommendations_combined = sorted_local + sorted_non_local
        top_recommendations = top_recommendations_combined[:7]

        print(f"\n--- Top 7 Job Provider Recommendations for {seeker_name} ---")
        print(f"Location Used for Proximity: {seeker_location_input.upper()}")
        print(f"Ranking: ({WEIGHT_FEATURE*100:.0f}% Skill Match + {WEIGHT_PROXIMITY*100:.0f}% Proximity Bonus)")
        print("{:<3} {:<30} {:>10} {:>10} {:>10} {:>15}".format("No.", "Provider Name", "Combined", "Feature", "Proximity", "Provider Location"))
        print("-" * 75)

        for rank, (name, (combined, feature, proximity)) in enumerate(top_recommendations):
            if df[df['Full Name'] == name].empty: continue
            provider_location_original = df[df['Full Name'] == name]['Location'].iloc[0]

            print("{:<3} {:<30} {:>10.4f} {:>10.4f} {:>10.1f} {:>15}".format(
                rank + 1, name, combined, feature, proximity, provider_location_original
            ))

# Execute the Recommendation System
if __name__ == '__main__':
    run_recommendation_system()

